INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '1', 'Aries', '', 'Bản ngã được thể hiện qua năng lượng tiên phong, quyết đoán và độc lập của Bạch Dương. Bạn tiếp cận thế giới xung quanh với tinh thần trực diện, dũng cảm và nhiệt huyết.', 'Trong cuộc sống hằng ngày, vị trí Nhà 1 ở Bạch Dương định hình phản ứng thực tế và cách bạn thể hiện bản thân. You approach life head-on with boundless energy. You are usually the first to start a project, jump into a new situation, or assert your opinions.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 1 và năng lượng Bạch Dương: Immense vitality, natural leadership, fearlessness, and the ability to inspire others through sheer willpower.', 'Thách thức cần lưu ý: Impulsiveness, a tendency to rush into things without planning, and potential aggression when faced with obstacles.', 'In relationships, you seek excitement and may dominate if you are not careful. You need a partner who respects your independence.', 'Learn patience and the value of seeing things through to completion rather than just starting them.', ARRAY['Nhà 1', 'Bạch Dương']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '1', 'Taurus', '', 'Bản ngã được thể hiện qua năng lượng kiên định, bền bỉ và thực tế của Kim Ngưu. Bạn tiếp cận thế giới xung quanh với tinh thần vững chắc, cẩn trọng và coi trọng chất lượng.', 'Trong cuộc sống hằng ngày, vị trí Nhà 1 ở Kim Ngưu định hình phản ứng thực tế và cách bạn thể hiện bản thân. You project a calm, steadfast demeanor. You prefer routine, value high-quality possessions, and approach changes with extreme caution.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 1 và năng lượng Kim Ngưu: Endurance, reliability, a strong sense of aesthetics, and the ability to manifest tangible results from abstract ideas.', 'Thách thức cần lưu ý: Stubbornness, resistance to necessary change, and a tendency to become overly attached to material comforts.', 'You are fiercely loyal and seek long-term stability in partnerships. You offer great comfort but can be possessive.', 'Embrace flexibility and understand that true security comes from within, not just from the material world.', ARRAY['Nhà 1', 'Kim Ngưu']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '1', 'Gemini', '', 'Bản ngã được thể hiện qua năng lượng nhanh trí, linh hoạt và tò mò của Song Tử. Bạn tiếp cận thế giới xung quanh với tinh thần cởi mở, đa dạng và giỏi giao tiếp.', 'Trong cuộc sống hằng ngày, vị trí Nhà 1 ở Song Tử định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are quick-witted, talkative, and constantly on the move. You likely have many varied interests and present yourself as youthful and inquisitive.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 1 và năng lượng Song Tử: Versatility, excellent communication skills, a sharp intellect, and the ability to multitask effortlessly.', 'Thách thức cần lưu ý: Nervous tension, superficiality, an inability to focus on one thing for long, and a tendency to gossip.', 'You need intellectual stimulation in relationships. Boredom is your biggest enemy in love, and you require a partner who is also a friend.', 'Develop mental focus and depth. Learn to commit to a singular path when necessary instead of scattering your energy.', ARRAY['Nhà 1', 'Song Tử']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '1', 'Cancer', '', 'Bản ngã được thể hiện qua năng lượng nhạy cảm, thấu cảm và chu đáo của Cự Giải. Bạn tiếp cận thế giới xung quanh với tinh thần ấm áp, bảo vệ và giàu tình cảm.', 'Trong cuộc sống hằng ngày, vị trí Nhà 1 ở Cự Giải định hình phản ứng thực tế và cách bạn thể hiện bản thân. You appear gentle, nurturing, and sometimes guarded. You are highly sensitive to the moods of others and deeply protective of your inner circle.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 1 và năng lượng Cự Giải: Incredible empathy, strong intuition, loyalty, and the ability to create a sense of home wherever you go.', 'Thách thức cần lưu ý: Moodiness, clinging to the past, a tendency to withdraw into your shell when hurt, and taking things too personally.', 'You seek deep emotional merging and fear abandonment. You nurture your partners but can become overly dependent.', 'Learn to separate your emotions from objective reality and establish healthy boundaries so you are not drained by others.', ARRAY['Nhà 1', 'Cự Giải']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '1', 'Leo', '', 'Bản ngã được thể hiện qua năng lượng kiêu hãnh, tự tin và sáng tạo của Sư Tử. Bạn tiếp cận thế giới xung quanh với tinh thần rực rỡ, hào phóng và cuốn hút.', 'Trong cuộc sống hằng ngày, vị trí Nhà 1 ở Sư Tử định hình phản ứng thực tế và cách bạn thể hiện bản thân. You have a commanding, dramatic presence and exude confidence. You are warm, generous, and naturally draw attention when entering a room.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 1 và năng lượng Sư Tử: Charisma, natural leadership, a huge heart, and the ability to inspire and uplift those around you.', 'Thách thức cần lưu ý: Arrogance, an excessive need for validation, vanity, and a tendency to overshadow others.', 'You are fiercely loyal and generous in love, seeking a partner who adores you and whom you can proudly show off.', 'True confidence does not require constant applause. Learn to validate yourself and share the spotlight with others.', ARRAY['Nhà 1', 'Sư Tử']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '1', 'Virgo', '', 'Bản ngã được thể hiện qua năng lượng tỉ mỉ, cẩn thận và thực tế của Xử Nữ. Bạn tiếp cận thế giới xung quanh với tinh thần chỉn chu, phân tích và có phương pháp.', 'Trong cuộc sống hằng ngày, vị trí Nhà 1 ở Xử Nữ định hình phản ứng thực tế và cách bạn thể hiện bản thân. You present yourself as practical, modest, and highly observant. You are often the one to fix problems and attend to the details others miss.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 1 và năng lượng Xử Nữ: Analytical brilliance, meticulous attention to detail, a strong work ethic, and a genuine desire to serve others.', 'Thách thức cần lưu ý: Perfectionism, extreme self-criticism, anxiety over small details, and a tendency to be overly critical of others.', 'You express love through acts of service. You can be picky in choosing a partner, seeking someone who meets your high standards.', 'Learn to accept imperfections in yourself and others. Cultivate self-compassion and realize that "good enough" is often perfect.', ARRAY['Nhà 1', 'Xử Nữ']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '1', 'Libra', '', 'Bản ngã được thể hiện qua năng lượng hài hòa, lịch thiệp và công bằng của Thiên Bình. Bạn tiếp cận thế giới xung quanh với tinh thần khéo léo, tinh tế và hướng tới sự cân bằng.', 'Trong cuộc sống hằng ngày, vị trí Nhà 1 ở Thiên Bình định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are charming, socially graceful, and highly invested in fairness. You strive to maintain peace and present an elegant, polished exterior.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 1 và năng lượng Thiên Bình: Diplomacy, a strong sense of justice, natural charm, and the ability to see all sides of a situation.', 'Thách thức cần lưu ý: Indecisiveness, a fear of confrontation, codependency, and compromising your own needs to please others.', 'Relationships are central to your identity. You seek a harmonious partnership but must avoid losing yourself in your significant other.', 'Develop a strong, independent sense of self. Learn that setting boundaries and engaging in healthy conflict are necessary for true harmony.', ARRAY['Nhà 1', 'Thiên Bình']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '1', 'Scorpio', '', 'Bản ngã được thể hiện qua năng lượng sâu sắc, kiên cường và thâm trầm của Bọ Cạp. Bạn tiếp cận thế giới xung quanh với tinh thần mãnh liệt, trực giác và bí ẩn.', 'Trong cuộc sống hằng ngày, vị trí Nhà 1 ở Bọ Cạp định hình phản ứng thực tế và cách bạn thể hiện bản thân. You project a magnetic, mysterious, and intense aura. You observe quietly but understand the underlying psychological currents of any room you enter.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 1 và năng lượng Bọ Cạp: Immense resilience, psychological depth, unwavering focus, and the ability to survive and transform through crises.', 'Thách thức cần lưu ý: Suspicion, a desire to control everything, jealousy, and holding onto grudges long after they should be released.', 'You seek absolute, soul-merging intimacy and loyalty. You are fiercely protective but can be prone to power struggles.', 'Learn to trust and let go of the need to control. True power comes from vulnerability and the ability to forgive.', ARRAY['Nhà 1', 'Bọ Cạp']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '1', 'Sagittarius', '', 'Bản ngã được thể hiện qua năng lượng phóng khoáng, lạc quan và yêu tự do của Nhân Mã. Bạn tiếp cận thế giới xung quanh với tinh thần thẳng thắn, rộng mở và giàu lý tưởng.', 'Trong cuộc sống hằng ngày, vị trí Nhà 1 ở Nhân Mã định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are optimistic, enthusiastic, and always looking toward the future. You come across as jovial, blunt, and fiercely independent.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 1 và năng lượng Nhân Mã: A visionary perspective, boundless optimism, honesty, and the ability to see the big picture and inspire others.', 'Thách thức cần lưu ý: Recklessness, a lack of tact, avoiding responsibilities, and a tendency to preach rather than converse.', 'You need a partner who shares your love for adventure and respects your need for freedom. Clinginess will drive you away.', 'Learn to balance your grand visions with practical details. Cultivate tact and realize that commitment does not always mean a loss of freedom.', ARRAY['Nhà 1', 'Nhân Mã']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '1', 'Capricorn', '', 'Bản ngã được thể hiện qua năng lượng kỷ luật, trách nhiệm và thực tế của Ma Kết. Bạn tiếp cận thế giới xung quanh với tinh thần kiên trì, bài bản và có tầm nhìn dài hạn.', 'Trong cuộc sống hằng ngày, vị trí Nhà 1 ở Ma Kết định hình phản ứng thực tế và cách bạn thể hiện bản thân. You project an aura of authority, maturity, and seriousness. You are highly pragmatic and focused on building a solid reputation.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 1 và năng lượng Ma Kết: Incredible discipline, strategic thinking, resilience, and the ability to handle massive responsibilities and achieve mastery.', 'Thách thức cần lưu ý: Pessimism, rigidity, prioritizing work over emotional well-being, and a fear of failure that can lead to depression.', 'You take relationships seriously and seek a partner who is ambitious and reliable. You show love by providing security rather than displaying emotion.', 'Allow yourself to be vulnerable and remember to enjoy the journey, not just the destination. Cultivate a work-life balance.', ARRAY['Nhà 1', 'Ma Kết']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '1', 'Aquarius', '', 'Bản ngã được thể hiện qua năng lượng độc đáo, tiến bộ và hướng tới cộng đồng của Bảo Bình. Bạn tiếp cận thế giới xung quanh với tinh thần đột phá, trí tuệ và phi truyền thống.', 'Trong cuộc sống hằng ngày, vị trí Nhà 1 ở Bảo Bình định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are highly individualistic, intellectual, and often march to the beat of your own drum. You present yourself as friendly but slightly detached.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 1 và năng lượng Bảo Bình: Originality, a brilliant and progressive mind, strong humanitarian values, and the ability to break outdated rules.', 'Thách thức cần lưu ý: Stubborn rebelliousness, emotional detachment, unpredictability, and a tendency to alienate others by being too contrarian.', 'You require a deep intellectual connection and absolute freedom. You treat your partner as your best friend but may struggle with deep emotional intimacy.', 'Learn to connect on a deeply emotional level, not just an intellectual one. True rebellion sometimes requires vulnerability.', ARRAY['Nhà 1', 'Bảo Bình']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '1', 'Pisces', '', 'Bản ngã được thể hiện qua năng lượng mềm mại, vị tha và sâu sắc của Song Ngư. Bạn tiếp cận thế giới xung quanh với tinh thần thấu cảm, lãng mạn và giàu trí tưởng tượng.', 'Trong cuộc sống hằng ngày, vị trí Nhà 1 ở Song Ngư định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are gentle, dreamy, and highly intuitive. You easily absorb the energies around you and have a deeply compassionate presence.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 1 và năng lượng Song Ngư: Boundless empathy, artistic inspiration, spiritual depth, and the ability to heal and comfort others.', 'Thách thức cần lưu ý: Escapism, a lack of boundaries, playing the victim, and getting lost in illusions or addictions to avoid harsh realities.', 'You seek a spiritual, transcendent union. You are incredibly romantic but prone to projecting idealized fantasies onto your partner.', 'Develop strong personal boundaries and ground yourself in reality. Learn to distinguish your own feelings from those of others.', ARRAY['Nhà 1', 'Song Ngư']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '2', 'Aries', '', 'Giá trị bản thân và khả năng quản lý tài chính gắn liền với đặc tính tiên phong, quyết đoán và độc lập của Bạch Dương. Bạn tạo ra thu nhập và sự an toàn vật chất thông qua sự trực diện, dũng cảm và nhiệt huyết.', 'Trong cuộc sống hằng ngày, vị trí Nhà 2 ở Bạch Dương định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are an impulsive spender and an aggressive earner. You prefer to make your own money through independent ventures rather than waiting for handouts.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 2 và năng lượng Bạch Dương: The ability to quickly generate income, fearless entrepreneurship, and a strong belief in your own capacity to provide.', 'Thách thức cần lưu ý: Financial impulsivity, spending money as fast as it is made, and a lack of long-term financial planning.', 'You value partners who are self-sufficient. Disputes over money in relationships often stem from your desire to have total control over your assets.', 'Learn the value of patience in financial matters. Cultivate saving habits and think about long-term security before making impulsive purchases.', ARRAY['Nhà 2', 'Bạch Dương']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '2', 'Taurus', '', 'Giá trị bản thân và khả năng quản lý tài chính gắn liền với đặc tính kiên định, bền bỉ và thực tế của Kim Ngưu. Bạn tạo ra thu nhập và sự an toàn vật chất thông qua sự vững chắc, cẩn trọng và coi trọng chất lượng.', 'Trong cuộc sống hằng ngày, vị trí Nhà 2 ở Kim Ngưu định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are highly practical with finances, preferring secure, long-term investments. You enjoy buying high-quality, luxurious items that stand the test of time.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 2 và năng lượng Kim Ngưu: Exceptional financial management, the ability to accumulate lasting wealth, and a profound appreciation for beauty and comfort.', 'Thách thức cần lưu ý: Extreme materialism, a fear of financial loss that leads to hoarding, and a stubborn refusal to adapt to new financial strategies.', 'You seek a partner who provides stability. You express value through giving tangible gifts and creating a comfortable home environment.', 'Understand that your true worth is not defined by your bank account. Learn to detach emotionally from material possessions.', ARRAY['Nhà 2', 'Kim Ngưu']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '2', 'Gemini', '', 'Giá trị bản thân và khả năng quản lý tài chính gắn liền với đặc tính nhanh trí, linh hoạt và tò mò của Song Tử. Bạn tạo ra thu nhập và sự an toàn vật chất thông qua sự cởi mở, đa dạng và giỏi giao tiếp.', 'Trong cuộc sống hằng ngày, vị trí Nhà 2 ở Song Tử định hình phản ứng thực tế và cách bạn thể hiện bản thân. You view money as a means to experience variety. You might hold down two jobs, trade stocks frequently, or earn money through writing, speaking, or sales.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 2 và năng lượng Song Tử: Financial adaptability, the ability to monetize ideas and information quickly, and a clever approach to budgeting.', 'Thách thức cần lưu ý: Frivolous spending on gadgets or books, financial inconsistency, and a tendency to jump from one earning scheme to another.', 'You value partners who are financially communicative and intellectually stimulating. Joint finances require constant, clear dialogue.', 'Focus your financial energy on one or two solid avenues rather than scattering your resources. Develop financial discipline.', ARRAY['Nhà 2', 'Song Tử']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '2', 'Cancer', '', 'Giá trị bản thân và khả năng quản lý tài chính gắn liền với đặc tính nhạy cảm, thấu cảm và chu đáo của Cự Giải. Bạn tạo ra thu nhập và sự an toàn vật chất thông qua sự ấm áp, bảo vệ và giàu tình cảm.', 'Trong cuộc sống hằng ngày, vị trí Nhà 2 ở Cự Giải định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are a careful saver, often holding onto money for a "rainy day." Your financial goals are usually centered around buying a home or providing for your family.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 2 và năng lượng Cự Giải: Excellent intuition regarding financial investments (especially real estate), thriftiness, and a strong protective instinct over resources.', 'Thách thức cần lưu ý: Emotional spending, hoarding resources out of fear of lack, and allowing your self-worth to fluctuate with your bank balance.', 'Financial security is a prerequisite for emotional intimacy. You need a partner who shares your conservative approach to money and family security.', 'Learn to separate your emotional well-being from your financial status. Trust that you can survive even if material circumstances change.', ARRAY['Nhà 2', 'Cự Giải']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '2', 'Leo', '', 'Giá trị bản thân và khả năng quản lý tài chính gắn liền với đặc tính kiêu hãnh, tự tin và sáng tạo của Sư Tử. Bạn tạo ra thu nhập và sự an toàn vật chất thông qua sự rực rỡ, hào phóng và cuốn hút.', 'Trong cuộc sống hằng ngày, vị trí Nhà 2 ở Sư Tử định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are a generous spender, often picking up the tab for friends. You view wealth as a way to enjoy luxury and demand a salary that reflects your high self-esteem.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 2 và năng lượng Sư Tử: Immense generosity, the ability to attract wealth through creative talents, and a positive, abundant mindset.', 'Thách thức cần lưu ý: Extravagance, living beyond your means to maintain appearances, and letting your ego dictate your financial decisions.', 'You express love through grand, expensive gestures. You expect your partner to appreciate your generosity and treat you like royalty in return.', 'Learn that your intrinsic value does not depend on luxury items or grand displays of wealth. Practice modest financial planning.', ARRAY['Nhà 2', 'Sư Tử']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '2', 'Virgo', '', 'Giá trị bản thân và khả năng quản lý tài chính gắn liền với đặc tính tỉ mỉ, cẩn thận và thực tế của Xử Nữ. Bạn tạo ra thu nhập và sự an toàn vật chất thông qua sự chỉn chu, phân tích và có phương pháp.', 'Trong cuộc sống hằng ngày, vị trí Nhà 2 ở Xử Nữ định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are highly organized with your money, rarely spending frivolously. You earn your income through specialized skills, service, and diligent effort.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 2 và năng lượng Xử Nữ: Superb budgeting skills, financial practicality, resourcefulness, and a strong work ethic that ensures steady income.', 'Thách thức cần lưu ý: Worrying excessively about money, undervaluing your own skills and charging less than you are worth, and extreme frugality.', 'In relationships, you prefer practical financial arrangements and clear budgets. You value a partner who is financially responsible and avoids waste.', 'Recognize your true value and do not be afraid to demand fair compensation. Learn that it is okay to spend money on pleasure occasionally.', ARRAY['Nhà 2', 'Xử Nữ']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '2', 'Libra', '', 'Giá trị bản thân và khả năng quản lý tài chính gắn liền với đặc tính hài hòa, lịch thiệp và công bằng của Thiên Bình. Bạn tạo ra thu nhập và sự an toàn vật chất thông qua sự khéo léo, tinh tế và hướng tới sự cân bằng.', 'Trong cuộc sống hằng ngày, vị trí Nhà 2 ở Thiên Bình định hình phản ứng thực tế và cách bạn thể hiện bản thân. You love to spend money on art, fashion, and creating a beautiful environment. You may struggle to balance your budget due to a desire for luxury.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 2 và năng lượng Thiên Bình: The ability to attract money through charm and social connections, a great eye for valuable aesthetics, and fairness in financial dealings.', 'Thách thức cần lưu ý: Overspending on luxuries to keep up appearances, indecisiveness in financial planning, and relying too heavily on a partner for financial security.', 'You view joint finances as a crucial part of marriage. You must ensure you do not compromise your own financial independence to keep the peace.', 'Learn to balance the checkbook as well as you balance relationships. Cultivate financial independence and avoid codependency in money matters.', ARRAY['Nhà 2', 'Thiên Bình']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '2', 'Sagittarius', '', 'Giá trị bản thân và khả năng quản lý tài chính gắn liền với đặc tính phóng khoáng, lạc quan và yêu tự do của Nhân Mã. Bạn tạo ra thu nhập và sự an toàn vật chất thông qua sự thẳng thắn, rộng mở và giàu lý tưởng.', 'Trong cuộc sống hằng ngày, vị trí Nhà 2 ở Nhân Mã định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are a natural risk-taker with finances, often believing that "the universe will provide." You spend money freely on experiences rather than objects.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 2 và năng lượng Nhân Mã: Abundant optimism that often attracts wealth, a talent for earning through teaching or publishing, and a healthy detachment from material greed.', 'Thách thức cần lưu ý: Reckless financial gambling, overestimating future income, ignoring budgets, and living beyond your means due to sheer optimism.', 'You need a partner who does not restrict your spending on travel and education. You hate financial constraints and penny-pinching in relationships.', 'Ground your financial optimism with practical planning. Learn to save for the future while still enjoying the present.', ARRAY['Nhà 2', 'Nhân Mã']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '2', 'Capricorn', '', 'Giá trị bản thân và khả năng quản lý tài chính gắn liền với đặc tính kỷ luật, trách nhiệm và thực tế của Ma Kết. Bạn tạo ra thu nhập và sự an toàn vật chất thông qua sự kiên trì, bài bản và có tầm nhìn dài hạn.', 'Trong cuộc sống hằng ngày, vị trí Nhà 2 ở Ma Kết định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are highly disciplined with money, viewing it as a measure of success. You are willing to work long and hard for financial stability and social status.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 2 và năng lượng Ma Kết: Exceptional financial discipline, strategic long-term planning, patience in investments, and the ability to build a lasting legacy.', 'Thách thức cần lưu ý: Extreme frugality bordering on stinginess, prioritizing wealth over personal relationships, and a deep-seated fear of poverty.', 'You look for a financially stable partner. Love and money are often tied to mutual ambition and the building of a secure, traditional life together.', 'Remember that money is a means to an end, not the end itself. Allow yourself to enjoy the fruits of your labor without guilt.', ARRAY['Nhà 2', 'Ma Kết']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '2', 'Aquarius', '', 'Giá trị bản thân và khả năng quản lý tài chính gắn liền với đặc tính độc đáo, tiến bộ và hướng tới cộng đồng của Bảo Bình. Bạn tạo ra thu nhập và sự an toàn vật chất thông qua sự đột phá, trí tuệ và phi truyền thống.', 'Trong cuộc sống hằng ngày, vị trí Nhà 2 ở Bảo Bình định hình phản ứng thực tế và cách bạn thể hiện bản thân. You may earn money through technology, science, or progressive organizations. You care less about material luxury and more about financial independence.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 2 và năng lượng Bảo Bình: Innovative ways of earning money, financial detachment that prevents greed, and a willingness to use wealth for collective good.', 'Thách thức cần lưu ý: Erratic income streams, sudden financial changes, and a rebellion against traditional saving and budgeting methods.', 'You prefer keeping your finances separate in relationships. You value a partner who respects your financial autonomy and unconventional choices.', 'Integrate some traditional financial stability into your unconventional life. A basic budget can provide the freedom you so desperately seek.', ARRAY['Nhà 2', 'Bảo Bình']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '2', 'Pisces', '', 'Giá trị bản thân và khả năng quản lý tài chính gắn liền với đặc tính mềm mại, vị tha và sâu sắc của Song Ngư. Bạn tạo ra thu nhập và sự an toàn vật chất thông qua sự thấu cảm, lãng mạn và giàu trí tưởng tượng.', 'Trong cuộc sống hằng ngày, vị trí Nhà 2 ở Song Ngư định hình phản ứng thực tế và cách bạn thể hiện bản thân. You have a fluid, sometimes confusing relationship with money. You are incredibly generous, often giving money away, but may struggle to track your expenses.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 2 và năng lượng Song Ngư: The ability to manifest wealth through art and intuition, immense generosity, and a lack of superficial materialism.', 'Thách thức cần lưu ý: Financial disorganization, being easily scammed or taken advantage of financially, and avoiding the practical reality of bills and budgets.', 'You are entirely unselfish in joint finances, which can lead to a partner taking advantage of you. You need a partner who can handle the practical financial details.', 'You must ground yourself in financial reality. Learn to set boundaries with your generosity and develop basic money management skills.', ARRAY['Nhà 2', 'Song Ngư']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '3', 'Aries', '', 'Tư duy, giao tiếp và khả năng học hỏi mang màu sắc tiên phong, quyết đoán và độc lập của Bạch Dương. Bạn tiếp thu thông tin và kết nối với môi trường xung quanh một cách trực diện, dũng cảm và nhiệt huyết.', 'Trong cuộc sống hằng ngày, vị trí Nhà 3 ở Bạch Dương định hình phản ứng thực tế và cách bạn thể hiện bản thân. You speak your mind quickly and forcefully. You are a fast learner who prefers to gather information rapidly and initiate conversations or debates.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 3 và năng lượng Bạch Dương: Decisiveness in thought, the ability to inspire others through speech, and a courageous approach to expressing your ideas.', 'Thách thức cần lưu ý: Impatience with slow thinkers, interrupting others, a tendency to argue for the sake of winning, and lacking follow-through on ideas.', 'You engage friends and siblings in lively debates. You need intellectual independence and can be easily frustrated by those who are overly sensitive to blunt talk.', 'Practice active listening. Learn that communication is a two-way street and that pausing before speaking can prevent unnecessary conflict.', ARRAY['Nhà 3', 'Bạch Dương']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '3', 'Taurus', '', 'Tư duy, giao tiếp và khả năng học hỏi mang màu sắc kiên định, bền bỉ và thực tế của Kim Ngưu. Bạn tiếp thu thông tin và kết nối với môi trường xung quanh một cách vững chắc, cẩn trọng và coi trọng chất lượng.', 'Trong cuộc sống hằng ngày, vị trí Nhà 3 ở Kim Ngưu định hình phản ứng thực tế và cách bạn thể hiện bản thân. You take your time to process information and form opinions. Once you make up your mind, you are incredibly steadfast and articulate your thoughts with practical clarity.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 3 và năng lượng Kim Ngưu: A strong, retentive memory, the ability to translate abstract ideas into tangible plans, and a soothing, reliable speaking voice.', 'Thách thức cần lưu ý: Mental stubbornness, a reluctance to accept new or abstract concepts, and being overly fixed in your opinions.', 'Your relationships with siblings or neighbors are usually stable and long-lasting. You communicate affection through practical advice and reliability.', 'Open your mind to concepts that cannot be physically touched or proven immediately. Embrace intellectual flexibility.', ARRAY['Nhà 3', 'Kim Ngưu']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '3', 'Gemini', '', 'Tư duy, giao tiếp và khả năng học hỏi mang màu sắc nhanh trí, linh hoạt và tò mò của Song Tử. Bạn tiếp thu thông tin và kết nối với môi trường xung quanh một cách cởi mở, đa dạng và giỏi giao tiếp.', 'Trong cuộc sống hằng ngày, vị trí Nhà 3 ở Song Tử định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are a natural chatterbox, constantly absorbing and sharing information. You likely read multiple books at once and have a vast network of acquaintances.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 3 và năng lượng Song Tử: Brilliant wit, exceptional adaptability, a talent for writing and speaking, and the ability to grasp complex concepts instantly.', 'Thách thức cần lưu ý: Mental restlessness, superficiality, a short attention span, and a tendency to scatter your intellectual energy in too many directions.', 'You thrive on constant communication with siblings and neighbors. You need varied intellectual stimulation to keep your daily relationships interesting.', 'Learn to focus your mind. Depth of knowledge is just as important as breadth of knowledge. Practice meditation to calm your active brain.', ARRAY['Nhà 3', 'Song Tử']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '3', 'Cancer', '', 'Tư duy, giao tiếp và khả năng học hỏi mang màu sắc nhạy cảm, thấu cảm và chu đáo của Cự Giải. Bạn tiếp thu thông tin và kết nối với môi trường xung quanh một cách ấm áp, bảo vệ và giàu tình cảm.', 'Trong cuộc sống hằng ngày, vị trí Nhà 3 ở Cự Giải định hình phản ứng thực tế và cách bạn thể hiện bản thân. You process information through how it makes you feel. You have a phenomenal memory for the past and communicate with deep emotional resonance.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 3 và năng lượng Cự Giải: Strong intuition, the ability to read between the lines, poetic expression, and a deeply sympathetic ear for others.', 'Thách thức cần lưu ý: Allowing emotions to cloud logical judgment, taking objective statements personally, and a tendency to communicate passive-aggressively.', 'You treat close friends and neighbors like family. Communication in these relationships is nurturing, but you can become easily hurt by harsh words.', 'Learn to detach your feelings from facts. Cultivate objective reasoning so that your emotions do not distort your perception of reality.', ARRAY['Nhà 3', 'Cự Giải']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '3', 'Leo', '', 'Tư duy, giao tiếp và khả năng học hỏi mang màu sắc kiêu hãnh, tự tin và sáng tạo của Sư Tử. Bạn tiếp thu thông tin và kết nối với môi trường xung quanh một cách rực rỡ, hào phóng và cuốn hút.', 'Trong cuộc sống hằng ngày, vị trí Nhà 3 ở Sư Tử định hình phản ứng thực tế và cách bạn thể hiện bản thân. You speak with authority and flair. You are a natural storyteller who knows how to captivate an audience and present your ideas creatively.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 3 và năng lượng Sư Tử: Charismatic communication, the ability to lead and motivate through speech, and a warm, expressive intellect.', 'Thách thức cần lưu ý: Intellectual arrogance, dominating conversations, a reluctance to listen to opposing views, and needing constant praise for your ideas.', 'You take pride in your siblings and local community. You expect loyalty and admiration in your daily interactions and can be deeply hurt by intellectual criticism.', 'Remember that a good leader also listens. Allow others to share the spotlight in conversations and learn to accept constructive feedback gracefully.', ARRAY['Nhà 3', 'Sư Tử']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '3', 'Virgo', '', 'Tư duy, giao tiếp và khả năng học hỏi mang màu sắc tỉ mỉ, cẩn thận và thực tế của Xử Nữ. Bạn tiếp thu thông tin và kết nối với môi trường xung quanh một cách chỉn chu, phân tích và có phương pháp.', 'Trong cuộc sống hằng ngày, vị trí Nhà 3 ở Xử Nữ định hình phản ứng thực tế và cách bạn thể hiện bản thân. You analyze information meticulously and notice details that everyone else misses. You communicate clearly, aiming for accuracy and usefulness.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 3 và năng lượng Xử Nữ: Exceptional organizational skills, a brilliant analytical mind, a talent for research, and clear, effective communication.', 'Thách thức cần lưu ý: Overthinking, getting lost in minor details, extreme self-criticism, and a tendency to be overly critical or nitpicky with others.', 'You express care for siblings and friends by offering practical help and solving their problems. You can be demanding regarding logic and facts.', 'Learn to see the big picture instead of agonizing over the details. Relax your critical mind and realize that not everything requires analysis.', ARRAY['Nhà 3', 'Xử Nữ']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '3', 'Libra', '', 'Tư duy, giao tiếp và khả năng học hỏi mang màu sắc hài hòa, lịch thiệp và công bằng của Thiên Bình. Bạn tiếp thu thông tin và kết nối với môi trường xung quanh một cách khéo léo, tinh tế và hướng tới sự cân bằng.', 'Trong cuộc sống hằng ngày, vị trí Nhà 3 ở Thiên Bình định hình phản ứng thực tế và cách bạn thể hiện bản thân. You carefully weigh all sides of an argument before speaking. You are an excellent mediator who uses language to smooth over conflicts and charm others.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 3 và năng lượng Thiên Bình: A natural talent for diplomacy, fair-mindedness, a refined way of speaking, and the ability to see multiple perspectives simultaneously.', 'Thách thức cần lưu ý: Indecisiveness, agreeing with others just to keep the peace, avoiding necessary confrontation, and intellectual codependency.', 'You seek harmonious, equal interactions with siblings and neighbors. You loathe crude communication and strive for intellectual partnerships.', 'Do not be afraid to voice an unpopular opinion. True intellectual integrity sometimes requires disrupting the peace to state the truth.', ARRAY['Nhà 3', 'Thiên Bình']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '3', 'Scorpio', '', 'Tư duy, giao tiếp và khả năng học hỏi mang màu sắc sâu sắc, kiên cường và thâm trầm của Bọ Cạp. Bạn tiếp thu thông tin và kết nối với môi trường xung quanh một cách mãnh liệt, trực giác và bí ẩn.', 'Trong cuộc sống hằng ngày, vị trí Nhà 3 ở Bọ Cạp định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are not interested in small talk; you want to know the hidden truth. You research obsessively and speak with an intensity that commands attention.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 3 và năng lượng Bọ Cạp: Profound psychological insight, the ability to uncover secrets, absolute focus, and a powerful, transformative intellect.', 'Thách thức cần lưu ý: Paranoia, an obsessive mind, holding onto dark thoughts, and using language to manipulate or sting others when hurt.', 'You are highly protective of your siblings and inner circle but demand absolute loyalty. You can be suspicious and communicate with a guarded intensity.', 'Use your penetrating mind for healing rather than control. Learn to trust others and realize that not everyone has hidden motives.', ARRAY['Nhà 3', 'Bọ Cạp']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '3', 'Sagittarius', '', 'Tư duy, giao tiếp và khả năng học hỏi mang màu sắc phóng khoáng, lạc quan và yêu tự do của Nhân Mã. Bạn tiếp thu thông tin và kết nối với môi trường xung quanh một cách thẳng thắn, rộng mở và giàu lý tưởng.', 'Trong cuộc sống hằng ngày, vị trí Nhà 3 ở Nhân Mã định hình phản ứng thực tế và cách bạn thể hiện bản thân. You think in terms of grand concepts and future possibilities. You are fiercely honest, sometimes to a fault, and love discussing philosophy or travel.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 3 và năng lượng Nhân Mã: Visionary thinking, a love for learning, unshakeable optimism, and the ability to inspire others with your broad perspective.', 'Thách thức cần lưu ý: Overlooking crucial details, dogmatism, speaking before thinking, and lacking the tact required for sensitive conversations.', 'You interact with friends and siblings in a jovial, freedom-loving manner. You enjoy philosophical debates but can inadvertently offend others with your bluntness.', 'Learn to pay attention to the details and cultivate tact. Honesty is a virtue, but it must be delivered with empathy to be effective.', ARRAY['Nhà 3', 'Nhân Mã']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '3', 'Capricorn', '', 'Tư duy, giao tiếp và khả năng học hỏi mang màu sắc kỷ luật, trách nhiệm và thực tế của Ma Kết. Bạn tiếp thu thông tin và kết nối với môi trường xung quanh một cách kiên trì, bài bản và có tầm nhìn dài hạn.', 'Trong cuộc sống hằng ngày, vị trí Nhà 3 ở Ma Kết định hình phản ứng thực tế và cách bạn thể hiện bản thân. You plan your words carefully and only speak when you have something meaningful to say. You think in terms of strategy, efficiency, and long-term goals.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 3 và năng lượng Ma Kết: Excellent executive functioning, the ability to manifest ideas into reality, a disciplined mind, and clear, authoritative communication.', 'Thách thức cần lưu ý: Pessimism, mental rigidity, a tendency to view everything as a transaction, and a fear of expressing vulnerable thoughts.', 'You act as an authority figure to siblings and neighbors. You communicate with a sense of duty and responsibility, valuing respect over warmth.', 'Allow yourself to think outside the rigid structures of duty and ambition. Cultivate a sense of humor and express your emotions more freely.', ARRAY['Nhà 3', 'Ma Kết']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '3', 'Aquarius', '', 'Tư duy, giao tiếp và khả năng học hỏi mang màu sắc độc đáo, tiến bộ và hướng tới cộng đồng của Bảo Bình. Bạn tiếp thu thông tin và kết nối với môi trường xung quanh một cách đột phá, trí tuệ và phi truyền thống.', 'Trong cuộc sống hằng ngày, vị trí Nhà 3 ở Bảo Bình định hình phản ứng thực tế và cách bạn thể hiện bản thân. You process information logically but in entirely unique ways. You love discussing progressive ideas, technology, and social reform with your network.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 3 và năng lượng Bảo Bình: Originality, a brilliant and objective intellect, humanitarian ideals, and the ability to grasp complex, abstract concepts easily.', 'Thách thức cần lưu ý: Intellectual superiority, emotional detachment, extreme stubbornness regarding your unique views, and rebellious communication.', 'You view your siblings and local community as part of a larger collective. You communicate as a friend but may struggle with deep emotional empathy.', 'Remember that intellect is only one part of the human experience. Learn to integrate emotional intelligence into your brilliant, logical mind.', ARRAY['Nhà 3', 'Bảo Bình']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '3', 'Pisces', '', 'Tư duy, giao tiếp và khả năng học hỏi mang màu sắc mềm mại, vị tha và sâu sắc của Song Ngư. Bạn tiếp thu thông tin và kết nối với môi trường xung quanh một cách thấu cảm, lãng mạn và giàu trí tưởng tượng.', 'Trong cuộc sống hằng ngày, vị trí Nhà 3 ở Song Ngư định hình phản ứng thực tế và cách bạn thể hiện bản thân. You think in images and feelings rather than logic. You absorb information osmotically and communicate through art, music, or subtle emotional cues.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 3 và năng lượng Song Ngư: Profound imagination, spiritual insight, the ability to communicate with absolute empathy, and poetic brilliance.', 'Thách thức cần lưu ý: Lack of focus, mental confusion, a tendency to daydream instead of dealing with reality, and a struggle to articulate thoughts clearly.', 'You share a deep, psychic bond with siblings and friends. You are deeply compassionate but can be easily overwhelmed by their mental noise.', 'Ground your mind in logic and practical reality. Practice expressing your vast internal world in clear, concise language to avoid misunderstandings.', ARRAY['Nhà 3', 'Song Ngư']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '4', 'Aries', '', 'Nền tảng gia đình, nguồn cội và không gian an toàn nội tâm thấm đượm năng lượng tiên phong, quyết đoán và độc lập của Bạch Dương. Bạn tìm kiếm sự bình yên thông qua trực diện, dũng cảm và nhiệt huyết.', 'Trong cuộc sống hằng ngày, vị trí Nhà 4 ở Bạch Dương định hình phản ứng thực tế và cách bạn thể hiện bản thân. You view your home as a place of activity rather than just rest. You likely took on independence early in life and may have experienced a dynamic or assertive family environment.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 4 và năng lượng Bạch Dương: Fierce protection of family, the ability to act decisively in domestic crises, and fostering independence in those you live with.', 'Thách thức cần lưu ý: Arguments or impatience at home, a lack of peace in the domestic sphere, and difficulty settling down in one place.', 'You need a partner who respects your need to be the "head of the household" or at least your need for personal autonomy at home.', 'Learn to cultivate peace and stillness in your private life. Your home should also be a sanctuary, not just a battlefield.', ARRAY['Nhà 4', 'Bạch Dương']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '4', 'Taurus', '', 'Nền tảng gia đình, nguồn cội và không gian an toàn nội tâm thấm đượm năng lượng kiên định, bền bỉ và thực tế của Kim Ngưu. Bạn tìm kiếm sự bình yên thông qua vững chắc, cẩn trọng và coi trọng chất lượng.', 'Trong cuộc sống hằng ngày, vị trí Nhà 4 ở Kim Ngưu định hình phản ứng thực tế và cách bạn thể hiện bản thân. You invest heavily in your living space, preferring high-quality, comfortable furnishings. Your family life is likely stable, traditional, and centered around good food and comfort.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 4 và năng lượng Kim Ngưu: Creating a profoundly safe and beautiful home environment, loyalty to family traditions, and providing reliable emotional and material support.', 'Thách thức cần lưu ý: Stubbornness regarding domestic changes, hoarding possessions, and staying in unhealthy living situations purely out of a desire for stability.', 'You express love to your family through material provision and physical affection. You need a partner who values domestic tranquility.', 'Embrace the fact that true security is internal. Learn to accept necessary changes in your domestic life without panic.', ARRAY['Nhà 4', 'Kim Ngưu']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '4', 'Gemini', '', 'Nền tảng gia đình, nguồn cội và không gian an toàn nội tâm thấm đượm năng lượng nhanh trí, linh hoạt và tò mò của Song Tử. Bạn tìm kiếm sự bình yên thông qua cởi mở, đa dạng và giỏi giao tiếp.', 'Trong cuộc sống hằng ngày, vị trí Nhà 4 ở Song Tử định hình phản ứng thực tế và cách bạn thể hiện bản thân. Your home is likely filled with books, gadgets, and constant conversation. You may view your living situation flexibly and could have multiple places you call "home."', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 4 và năng lượng Song Tử: An intellectually stimulating domestic life, adaptability to changing living situations, and a youthful, communicative approach to family.', 'Thách thức cần lưu ý: Restlessness at home, a lack of deep emotional grounding, and a tendency to intellectualize feelings rather than experiencing them.', 'You need a partner who can keep up with a fast-paced, communicative household. Silence at home makes you uncomfortable.', 'Learn to ground yourself emotionally. Create spaces in your home dedicated to quiet reflection, away from constant mental stimulation.', ARRAY['Nhà 4', 'Song Tử']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '4', 'Cancer', '', 'Nền tảng gia đình, nguồn cội và không gian an toàn nội tâm thấm đượm năng lượng nhạy cảm, thấu cảm và chu đáo của Cự Giải. Bạn tìm kiếm sự bình yên thông qua ấm áp, bảo vệ và giàu tình cảm.', 'Trong cuộc sống hằng ngày, vị trí Nhà 4 ở Cự Giải định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are deeply attached to your roots and your family. Your home is a private sanctuary where you retreat to heal and protect yourself from the outside world.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 4 và năng lượng Cự Giải: Profound emotional intelligence regarding family, the ability to create a truly nurturing environment, and a strong connection to heritage.', 'Thách thức cần lưu ý: Clinging to the past, excessive nostalgia, suffocating family members with over-protectiveness, and retreating into your shell when threatened.', 'You seek a partner who feels like "home." Emotional security is the prerequisite for any deep domestic partnership.', 'Learn to differentiate between healthy nurturing and emotional codependency. Allow your loved ones the space to grow independently.', ARRAY['Nhà 4', 'Cự Giải']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '4', 'Leo', '', 'Nền tảng gia đình, nguồn cội và không gian an toàn nội tâm thấm đượm năng lượng kiêu hãnh, tự tin và sáng tạo của Sư Tử. Bạn tìm kiếm sự bình yên thông qua rực rỡ, hào phóng và cuốn hút.', 'Trong cuộc sống hằng ngày, vị trí Nhà 4 ở Sư Tử định hình phản ứng thực tế và cách bạn thể hiện bản thân. You take great pride in your home and family, often hosting gatherings to show them off. Childhood may have centered around a dominant or highly expressive parent.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 4 và năng lượng Sư Tử: Immense generosity toward family, a warm and welcoming domestic environment, and the ability to instill confidence in your loved ones.', 'Thách thức cần lưu ý: Dictatorial behavior at home, demanding constant attention from family members, and prioritizing the appearance of the home over its emotional warmth.', 'You are the protective leader of your family. You need a partner who admires your domestic efforts and allows you to shine at home.', 'Learn that true leadership at home involves serving and listening, not just commanding. Share the domestic spotlight.', ARRAY['Nhà 4', 'Sư Tử']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '4', 'Virgo', '', 'Nền tảng gia đình, nguồn cội và không gian an toàn nội tâm thấm đượm năng lượng tỉ mỉ, cẩn thận và thực tế của Xử Nữ. Bạn tìm kiếm sự bình yên thông qua chỉn chu, phân tích và có phương pháp.', 'Trong cuộc sống hằng ngày, vị trí Nhà 4 ở Xử Nữ định hình phản ứng thực tế và cách bạn thể hiện bản thân. You maintain a tidy, highly organized home. Your childhood may have involved a focus on chores, health, or practical duties rather than emotional expression.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 4 và năng lượng Xử Nữ: Creating a healthy, efficient, and well-managed household, dedicating yourself to the practical care of family members, and attention to detail.', 'Thách thức cần lưu ý: Over-criticizing family members, an inability to relax at home due to a never-ending list of chores, and anxiety regarding domestic perfection.', 'You show love at home through acts of service. You need a partner who appreciates cleanliness and practical contribution.', 'Learn to relax your standards at home. A home is meant to be lived in, not just cleaned. Cultivate emotional warmth over mere efficiency.', ARRAY['Nhà 4', 'Xử Nữ']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '4', 'Libra', '', 'Nền tảng gia đình, nguồn cội và không gian an toàn nội tâm thấm đượm năng lượng hài hòa, lịch thiệp và công bằng của Thiên Bình. Bạn tìm kiếm sự bình yên thông qua khéo léo, tinh tế và hướng tới sự cân bằng.', 'Trong cuộc sống hằng ngày, vị trí Nhà 4 ở Thiên Bình định hình phản ứng thực tế và cách bạn thể hiện bản thân. You strive to create a beautiful, harmonious living environment. You detest conflict at home and may have grown up in an environment that prioritized appearances or diplomacy.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 4 và năng lượng Thiên Bình: Excellent taste in home decor, the ability to mediate family disputes, and creating a truly welcoming, peaceful atmosphere.', 'Thách thức cần lưu ý: Sweeping domestic problems under the rug to avoid arguments, indecisiveness regarding household matters, and relying on a partner to create the home.', 'You view the home as a shared enterprise and hate living alone. You need a domestic partner who values peace as much as you do.', 'Learn that healthy conflict is sometimes necessary to maintain true domestic harmony. Do not compromise your own needs just to keep the peace.', ARRAY['Nhà 4', 'Thiên Bình']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '4', 'Scorpio', '', 'Nền tảng gia đình, nguồn cội và không gian an toàn nội tâm thấm đượm năng lượng sâu sắc, kiên cường và thâm trầm của Bọ Cạp. Bạn tìm kiếm sự bình yên thông qua mãnh liệt, trực giác và bí ẩn.', 'Trong cuộc sống hằng ngày, vị trí Nhà 4 ở Bọ Cạp định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are fiercely protective of your private life. Your home is a place of deep psychological renewal, and you only allow highly trusted individuals into your inner sanctum.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 4 và năng lượng Bọ Cạp: Incredible emotional resilience, the ability to support family through massive crises, and a deep, unspoken understanding of familial bonds.', 'Thách thức cần lưu ý: Paranoia, holding onto childhood resentments, controlling behavior within the family, and a tendency to create unnecessary domestic drama.', 'You demand absolute loyalty and emotional depth from those you live with. Betrayal in the domestic sphere is unforgivable to you.', 'Learn to let go of past familial traumas. Trust that your home can be a place of light and relaxation, not just a bunker for survival.', ARRAY['Nhà 4', 'Bọ Cạp']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '4', 'Sagittarius', '', 'Nền tảng gia đình, nguồn cội và không gian an toàn nội tâm thấm đượm năng lượng phóng khoáng, lạc quan và yêu tự do của Nhân Mã. Bạn tìm kiếm sự bình yên thông qua thẳng thắn, rộng mở và giàu lý tưởng.', 'Trong cuộc sống hằng ngày, vị trí Nhà 4 ở Nhân Mã định hình phản ứng thực tế và cách bạn thể hiện bản thân. You may come from a diverse, religious, or well-traveled family. You dislike feeling tied down to one location and prefer a home that feels spacious and culturally rich.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 4 và năng lượng Nhân Mã: A tolerant and optimistic domestic environment, the ability to make a home anywhere in the world, and inspiring a love of learning in family members.', 'Thách thức cần lưu ý: Avoiding domestic responsibilities, a lack of rootedness that can lead to feeling lost, and preaching at family members rather than listening.', 'You need a partner who respects your need for space and adventure, even within the domestic sphere. Clingy family dynamics suffocate you.', 'Learn the value of putting down roots. Freedom is wonderful, but a stable home base can provide the security needed for even greater adventures.', ARRAY['Nhà 4', 'Nhân Mã']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '4', 'Capricorn', '', 'Nền tảng gia đình, nguồn cội và không gian an toàn nội tâm thấm đượm năng lượng kỷ luật, trách nhiệm và thực tế của Ma Kết. Bạn tìm kiếm sự bình yên thông qua kiên trì, bài bản và có tầm nhìn dài hạn.', 'Trong cuộc sống hằng ngày, vị trí Nhà 4 ở Ma Kết định hình phản ứng thực tế và cách bạn thể hiện bản thân. You view the home as a serious responsibility. You take charge of domestic matters and strive to build a solid, respectable family legacy.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 4 và năng lượng Ma Kết: Providing immense material security for your family, preserving family traditions, and a stoic resilience that anchors the household.', 'Thách thức cần lưu ý: Emotional coldness at home, treating family members like employees, and a relentless focus on duty that crushes spontaneous joy.', 'You express care by providing structure and security. You need a partner who is equally responsible and respects traditional domestic roles.', 'Learn to separate your career ambitions from your private life. Allow your home to be a place of emotional vulnerability and relaxation.', ARRAY['Nhà 4', 'Ma Kết']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '4', 'Aquarius', '', 'Nền tảng gia đình, nguồn cội và không gian an toàn nội tâm thấm đượm năng lượng độc đáo, tiến bộ và hướng tới cộng đồng của Bảo Bình. Bạn tìm kiếm sự bình yên thông qua đột phá, trí tuệ và phi truyền thống.', 'Trong cuộc sống hằng ngày, vị trí Nhà 4 ở Bảo Bình định hình phản ứng thực tế và cách bạn thể hiện bản thân. Your childhood may have been unusual or disruptive. You prefer a living situation that defies tradition, perhaps living communally or maintaining a highly independent household.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 4 và năng lượng Bảo Bình: A tolerant, open-minded family dynamic, welcoming diverse people into your home, and fostering independence in your loved ones.', 'Thách thức cần lưu ý: Emotional detachment from family, unpredictability that creates an unstable home life, and rebelling against domestic routines just for the sake of it.', 'You treat family members like friends. You need a partner who allows you a massive amount of personal space within the home.', 'Learn to cultivate deep, emotional roots, not just intellectual ones. Your family needs your heart just as much as your mind.', ARRAY['Nhà 4', 'Bảo Bình']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '4', 'Pisces', '', 'Nền tảng gia đình, nguồn cội và không gian an toàn nội tâm thấm đượm năng lượng mềm mại, vị tha và sâu sắc của Song Ngư. Bạn tìm kiếm sự bình yên thông qua thấu cảm, lãng mạn và giàu trí tưởng tượng.', 'Trong cuộc sống hằng ngày, vị trí Nhà 4 ở Song Ngư định hình phản ứng thực tế và cách bạn thể hiện bản thân. You seek a mystical or highly artistic home environment. Your boundaries with family may be blurred, and your childhood may have involved sacrifice or a lack of clear structure.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 4 và năng lượng Song Ngư: Profound empathy for family members, creating a spiritually uplifting domestic space, and unconditional love for your roots.', 'Thách thức cần lưu ý: A lack of domestic boundaries, enabling toxic family behavior, a chaotic or disorganized home life, and a tendency to play the martyr at home.', 'You seek a soulful, almost psychic connection with those you live with. You must be careful not to absorb the negative emotions of your household.', 'Establish clear, firm boundaries with your family. Learn to ground your domestic life in practical reality so your home does not dissolve into chaos.', ARRAY['Nhà 4', 'Song Ngư']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '5', 'Aries', '', 'Năng lực sáng tạo, niềm vui và trải nghiệm tình yêu tỏa sáng qua lăng kính tiên phong, quyết đoán và độc lập của Bạch Dương. Bạn thể hiện sự đam mê một cách trực diện, dũng cảm và nhiệt huyết.', 'Trong cuộc sống hằng ngày, vị trí Nhà 5 ở Bạch Dương định hình phản ứng thực tế và cách bạn thể hiện bản thân. You dive headfirst into romances and hobbies with boundless enthusiasm. You love sports, active games, and being the bold initiator in love affairs.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 5 và năng lượng Bạch Dương: Fearless self-expression, a vibrant and infectious joy, the ability to infuse projects with massive energy, and a playful, childlike spirit.', 'Thách thức cần lưu ý: Losing interest quickly once the thrill is gone, impulsivity in gambling or romance, and a tendency to be aggressive or overly competitive in fun.', 'In romance, you are passionate and direct. You need a lover who can match your energy and keep you on your toes.', 'Learn to sustain your passions past the initial spark. True creative mastery and deep romance require patience and endurance.', ARRAY['Nhà 5', 'Bạch Dương']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '5', 'Taurus', '', 'Năng lực sáng tạo, niềm vui và trải nghiệm tình yêu tỏa sáng qua lăng kính kiên định, bền bỉ và thực tế của Kim Ngưu. Bạn thể hiện sự đam mê một cách vững chắc, cẩn trọng và coi trọng chất lượng.', 'Trong cuộc sống hằng ngày, vị trí Nhà 5 ở Kim Ngưu định hình phản ứng thực tế và cách bạn thể hiện bản thân. Your approach to romance is slow, sensual, and steady. You enjoy hobbies that produce something beautiful and lasting, like gardening, pottery, or music.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 5 và năng lượng Kim Ngưu: Steadfast dedication to creative projects, an incredible capacity for sensual enjoyment, and unwavering loyalty in romance once committed.', 'Thách thức cần lưu ý: Possessiveness in love, a reluctance to try new hobbies, and a tendency to prioritize material pleasure over emotional depth.', 'You are a deeply affectionate and reliable lover. You express romance through physical touch and luxurious gifts, seeking long-term stability.', 'Allow spontaneity into your romantic and creative life. Do not let the need for security stifle your artistic experimentation.', ARRAY['Nhà 5', 'Kim Ngưu']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '5', 'Gemini', '', 'Năng lực sáng tạo, niềm vui và trải nghiệm tình yêu tỏa sáng qua lăng kính nhanh trí, linh hoạt và tò mò của Song Tử. Bạn thể hiện sự đam mê một cách cởi mở, đa dạng và giỏi giao tiếp.', 'Trong cuộc sống hằng ngày, vị trí Nhà 5 ở Song Tử định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are flirtatious, witty, and need constant mental engagement to stay interested in a lover or a hobby. You likely have many creative projects going on simultaneously.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 5 và năng lượng Song Tử: Exceptional verbal creativity, the ability to keep romance fun and lighthearted, and a brilliant, adaptable approach to artistic expression.', 'Thách thức cần lưu ý: Fickleness in love, abandoning creative projects halfway through, and intellectualizing emotions rather than truly feeling them in romance.', 'You need a partner who is, first and foremost, a fascinating conversationalist. Boredom is the quickest way to end a romance with you.', 'Learn to focus your creative energy on completing one project at a time. In love, strive for emotional depth beyond just clever banter.', ARRAY['Nhà 5', 'Song Tử']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '5', 'Cancer', '', 'Năng lực sáng tạo, niềm vui và trải nghiệm tình yêu tỏa sáng qua lăng kính nhạy cảm, thấu cảm và chu đáo của Cự Giải. Bạn thể hiện sự đam mê một cách ấm áp, bảo vệ và giàu tình cảm.', 'Trong cuộc sống hằng ngày, vị trí Nhà 5 ở Cự Giải định hình phản ứng thực tế và cách bạn thể hiện bản thân. You pour your heart into your creative endeavors and romantic relationships. You may have a strong desire for children or treat your creative projects as your "babies."', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 5 và năng lượng Cự Giải: Profound emotional depth in art, fiercely protective love, and a nurturing approach to romance that makes partners feel incredibly safe.', 'Thách thức cần lưu ý: Over-attachment to lovers, getting easily hurt by minor criticisms of your creative work, and a tendency to smother those you care about.', 'You are deeply romantic and seek soul-level merging. You need a lover who appreciates your sensitivity and offers absolute emotional security.', 'Learn to let go of your creations and your lovers when necessary. True love and art require breathing room to flourish independently.', ARRAY['Nhà 5', 'Cự Giải']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '5', 'Leo', '', 'Năng lực sáng tạo, niềm vui và trải nghiệm tình yêu tỏa sáng qua lăng kính kiêu hãnh, tự tin và sáng tạo của Sư Tử. Bạn thể hiện sự đam mê một cách rực rỡ, hào phóng và cuốn hút.', 'Trong cuộc sống hằng ngày, vị trí Nhà 5 ở Sư Tử định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are a natural performer, whether on a literal stage or in your daily life. You treat romance like a cinematic love story and demand adoration.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 5 và năng lượng Sư Tử: Immense creative charisma, a huge capacity for joy and playfulness, generosity in love, and the ability to inspire audiences.', 'Thách thức cần lưu ý: Excessive need for applause, dramatic ego clashes in romance, vanity, and a tendency to treat lovers as an audience rather than equals.', 'In romance, you are fiercely loyal and expect to be treated like royalty. You shower your lovers with grand gestures and demand the same in return.', 'Learn that your creative worth is intrinsic, not dependent on external validation. In love, remember to shine the spotlight on your partner as well.', ARRAY['Nhà 5', 'Sư Tử']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '5', 'Virgo', '', 'Năng lực sáng tạo, niềm vui và trải nghiệm tình yêu tỏa sáng qua lăng kính tỉ mỉ, cẩn thận và thực tế của Xử Nữ. Bạn thể hiện sự đam mê một cách chỉn chu, phân tích và có phương pháp.', 'Trong cuộc sống hằng ngày, vị trí Nhà 5 ở Xử Nữ định hình phản ứng thực tế và cách bạn thể hiện bản thân. You find joy in hobbies that require precision and skill, like writing, coding, or crafts. You are modest in romance and express love through practical helpfulness.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 5 và năng lượng Xử Nữ: Masterful technical skills in art, a dedication to perfecting your craft, and a reliable, attentive approach to romantic partners.', 'Thách thức cần lưu ý: Over-analyzing romance, being overly critical of your own creative work (often preventing you from sharing it), and struggling to just relax and have fun.', 'You are picky in love, seeking a partner who meets your high standards. You show affection by fixing problems and managing the details of your lover’s life.', 'Learn to silence your inner critic. Creativity is often messy, and romance requires vulnerability. Allow yourself to enjoy the process without demanding perfection.', ARRAY['Nhà 5', 'Xử Nữ']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '5', 'Libra', '', 'Năng lực sáng tạo, niềm vui và trải nghiệm tình yêu tỏa sáng qua lăng kính hài hòa, lịch thiệp và công bằng của Thiên Bình. Bạn thể hiện sự đam mê một cách khéo léo, tinh tế và hướng tới sự cân bằng.', 'Trong cuộc sống hằng ngày, vị trí Nhà 5 ở Thiên Bình định hình phản ứng thực tế và cách bạn thể hiện bản thân. You have a refined sense of beauty and likely enjoy the arts, fashion, or design. You are highly romantic and feel most creatively inspired when collaborating with others.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 5 và năng lượng Thiên Bình: Exceptional artistic taste, natural charm that attracts romance effortlessly, and a talent for creating beauty and harmony in all endeavors.', 'Thách thức cần lưu ý: Becoming overly dependent on a romantic partner for happiness, indecisiveness in creative projects, and compromising your art just to please others.', 'You are a true romantic, seeking a fairy-tale partnership. You view love as an equal exchange and detest vulgarity or conflict in romance.', 'Learn to find your creative muse within yourself, not just in a partner. Cultivate the ability to stand alone and create art that is uniquely yours.', ARRAY['Nhà 5', 'Thiên Bình']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '5', 'Scorpio', '', 'Năng lực sáng tạo, niềm vui và trải nghiệm tình yêu tỏa sáng qua lăng kính sâu sắc, kiên cường và thâm trầm của Bọ Cạp. Bạn thể hiện sự đam mê một cách mãnh liệt, trực giác và bí ẩn.', 'Trong cuộc sống hằng ngày, vị trí Nhà 5 ở Bọ Cạp định hình phản ứng thực tế và cách bạn thể hiện bản thân. You do not do casual romance; you seek soul-consuming passion. Your creative projects are often profound, psychological, or deal with taboo subjects.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 5 và năng lượng Bọ Cạp: Magnetic romantic presence, the ability to create incredibly powerful and transformative art, and unwavering loyalty once trust is established.', 'Thách thức cần lưu ý: Obsessive jealousy, a need to control romantic partners, a tendency toward destructive dramatic affairs, and hoarding your creative work out of paranoia.', 'You demand absolute intimacy and transparency from a lover. You are fiercely protective but can easily fall into power struggles in romance.', 'Learn to release control in love and art. Trust that vulnerability is not weakness, and allow your intense passions to heal rather than destroy.', ARRAY['Nhà 5', 'Bọ Cạp']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '5', 'Sagittarius', '', 'Năng lực sáng tạo, niềm vui và trải nghiệm tình yêu tỏa sáng qua lăng kính phóng khoáng, lạc quan và yêu tự do của Nhân Mã. Bạn thể hiện sự đam mê một cách thẳng thắn, rộng mở và giàu lý tưởng.', 'Trong cuộc sống hằng ngày, vị trí Nhà 5 ở Nhân Mã định hình phản ứng thực tế và cách bạn thể hiện bản thân. You approach romance as a grand adventure, enjoying playful and diverse affairs. You find creative inspiration through travel, philosophy, and learning about different cultures.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 5 và năng lượng Nhân Mã: Boundless enthusiasm for creative projects, a fun and jovial approach to romance, and the ability to inspire others with your visionary ideas.', 'Thách thức cần lưu ý: Fear of commitment in romance, abandoning creative projects when they become tedious, and a tendency to gamble recklessly for fun.', 'You need a lover who is also an adventurer and a philosopher. You despise feeling tied down and require immense freedom in your romantic life.', 'Learn the value of creative discipline. While exploration is vital, true mastery requires sticking with a project or a partner through the mundane moments.', ARRAY['Nhà 5', 'Nhân Mã']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '5', 'Capricorn', '', 'Năng lực sáng tạo, niềm vui và trải nghiệm tình yêu tỏa sáng qua lăng kính kỷ luật, trách nhiệm và thực tế của Ma Kết. Bạn thể hiện sự đam mê một cách kiên trì, bài bản và có tầm nhìn dài hạn.', 'Trong cuộc sống hằng ngày, vị trí Nhà 5 ở Ma Kết định hình phản ứng thực tế và cách bạn thể hiện bản thân. You find pleasure in building things that last. Your creative projects often have a practical or business application. In romance, you take your time and prefer traditional courtship.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 5 và năng lượng Ma Kết: Exceptional discipline in mastering creative skills, the ability to turn hobbies into successful businesses, and absolute reliability in romantic commitments.', 'Thách thức cần lưu ý: Suppressing your inner child, a fear of taking creative risks, treating romance like a business transaction, and struggling to just let loose and have fun.', 'You seek a partner who is ambitious and respectable. You express love by providing security and structure rather than grand emotional displays.', 'Allow yourself to experience joy just for the sake of joy, not for achievement. Unchain your inner child and let yourself play without an agenda.', ARRAY['Nhà 5', 'Ma Kết']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '5', 'Aquarius', '', 'Năng lực sáng tạo, niềm vui và trải nghiệm tình yêu tỏa sáng qua lăng kính độc đáo, tiến bộ và hướng tới cộng đồng của Bảo Bình. Bạn thể hiện sự đam mê một cách đột phá, trí tuệ và phi truyền thống.', 'Trong cuộc sống hằng ngày, vị trí Nhà 5 ở Bảo Bình định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are drawn to unique, futuristic, or eccentric hobbies. In romance, you are friendly but detached, preferring unconventional relationship structures.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 5 và năng lượng Bảo Bình: Brilliant originality, the ability to invent entirely new forms of artistic expression, and a tolerant, open-minded approach to love.', 'Thách thức cần lưu ý: Emotional detachment that frustrates romantic partners, rebelling against creative norms just to be contrary, and a fear of deep, messy emotional intimacy.', 'You need a lover who is your best friend first and foremost. You demand intellectual freedom and will quickly exit any relationship that feels stifling.', 'Learn to integrate the heart with the mind. True creative genius and fulfilling romance require emotional depth, not just intellectual brilliance.', ARRAY['Nhà 5', 'Bảo Bình']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '5', 'Pisces', '', 'Năng lực sáng tạo, niềm vui và trải nghiệm tình yêu tỏa sáng qua lăng kính mềm mại, vị tha và sâu sắc của Song Ngư. Bạn thể hiện sự đam mê một cách thấu cảm, lãng mạn và giàu trí tưởng tượng.', 'Trong cuộc sống hằng ngày, vị trí Nhà 5 ở Song Ngư định hình phản ứng thực tế và cách bạn thể hiện bản thân. Your creative potential is massive, often channeled through music, film, or poetry. In romance, you are the ultimate dreamer, seeking a transcendent soulmate connection.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 5 và năng lượng Song Ngư: Profound artistic inspiration drawn from the collective unconscious, supreme romantic devotion, and a magical, enchanting creative presence.', 'Thách thức cần lưu ý: Getting lost in illusions, falling for unavailable or toxic partners (the savior/victim complex), and a lack of discipline to actually finish creative projects.', 'You are incredibly romantic and prone to projecting your fantasies onto your lover. You must be careful not to lose your identity in a relationship.', 'Ground your vast imagination in reality. Develop the discipline to manifest your dreams into actual art, and learn to see your romantic partners as they truly are.', ARRAY['Nhà 5', 'Song Ngư']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '6', 'Aries', '', 'Kỷ luật công việc, chăm sóc sức khỏe và tinh thần phục vụ mang đặc đặc tính tiên phong, quyết đoán và độc lập của Bạch Dương. Bạn hoàn thành trách nhiệm hằng ngày một cách trực diện, dũng cảm và nhiệt huyết.', 'Trong cuộc sống hằng ngày, vị trí Nhà 6 ở Bạch Dương định hình phản ứng thực tế và cách bạn thể hiện bản thân. You work at a rapid pace and prefer tasks that require quick action and initiative. You hate micromanagement and prefer to be your own boss in your daily duties.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 6 và năng lượng Bạch Dương: Incredible stamina, the ability to initiate new projects effortlessly, and a courageous approach to tackling difficult daily problems.', 'Thách thức cần lưu ý: Impatience with slow coworkers, a tendency to burn out by pushing yourself too hard physically, and a lack of follow-through on routine tasks.', 'You engage with colleagues dynamically but can be combative if you feel restricted. You need an active, competitive work environment.', 'Pace yourself. Learn that consistency is just as important as speed, and practice patience with those who do not share your rapid energy.', ARRAY['Nhà 6', 'Bạch Dương']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '6', 'Taurus', '', 'Kỷ luật công việc, chăm sóc sức khỏe và tinh thần phục vụ mang đặc đặc tính kiên định, bền bỉ và thực tế của Kim Ngưu. Bạn hoàn thành trách nhiệm hằng ngày một cách vững chắc, cẩn trọng và coi trọng chất lượng.', 'Trong cuộc sống hằng ngày, vị trí Nhà 6 ở Kim Ngưu định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are the bedrock of any workplace. You prefer a steady, predictable routine and have a talent for bringing structure and beauty into your daily tasks.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 6 và năng lượng Kim Ngưu: Unwavering reliability, exceptional endurance, the ability to produce high-quality, lasting work, and a practical approach to health.', 'Thách thức cần lưu ý: Stubborn resistance to new work methods, a tendency to get stuck in a rut, and potential laziness if you become too comfortable.', 'You are a steadfast colleague. You express care through practical help in the workplace but dislike sudden changes to the agenda.', 'Embrace innovation in your daily routines. Understand that flexibility can improve efficiency, even if it disrupts your comfort zone initially.', ARRAY['Nhà 6', 'Kim Ngưu']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '6', 'Gemini', '', 'Kỷ luật công việc, chăm sóc sức khỏe và tinh thần phục vụ mang đặc đặc tính nhanh trí, linh hoạt và tò mò của Song Tử. Bạn hoàn thành trách nhiệm hằng ngày một cách cởi mở, đa dạng và giỏi giao tiếp.', 'Trong cuộc sống hằng ngày, vị trí Nhà 6 ở Song Tử định hình phản ứng thực tế và cách bạn thể hiện bản thân. You likely juggle multiple tasks at once and thrive in environments where you can talk, write, or move around constantly. You need intellectual engagement to stay healthy.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 6 và năng lượng Song Tử: Exceptional multitasking abilities, brilliant problem-solving skills, and the capacity to adapt quickly to changing daily demands.', 'Thách thức cần lưu ý: Nervous exhaustion, scattered energy, leaving tasks unfinished, and a tendency to gossip or become easily distracted at work.', 'You are a communicative and lively coworker. You need a vibrant, talkative workplace to feel engaged.', 'Develop mental discipline. Focus your brilliant mind on completing one task before moving to the next. Practice mindfulness to calm your nervous system.', ARRAY['Nhà 6', 'Song Tử']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '6', 'Cancer', '', 'Kỷ luật công việc, chăm sóc sức khỏe và tinh thần phục vụ mang đặc đặc tính nhạy cảm, thấu cảm và chu đáo của Cự Giải. Bạn hoàn thành trách nhiệm hằng ngày một cách ấm áp, bảo vệ và giàu tình cảm.', 'Trong cuộc sống hằng ngày, vị trí Nhà 6 ở Cự Giải định hình phản ứng thực tế và cách bạn thể hiện bản thân. You approach your daily duties with care and intuition. You may work in fields related to caregiving, food, or real estate, and you are highly sensitive to the mood of your workplace.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 6 và năng lượng Cự Giải: Profound dedication to serving others, the ability to nurture coworkers, and a strong intuition for what needs to be done to create harmony.', 'Thách thức cần lưu ý: Taking workplace criticisms too personally, moody fluctuations that affect your productivity, and absorbing the stress of your environment.', 'You act as the "work parent," often caring for your colleagues. You need a supportive, emotionally safe work environment to thrive.', 'Establish emotional boundaries at work. Do not take on the emotional baggage of your coworkers, and learn to accept constructive criticism objectively.', ARRAY['Nhà 6', 'Cự Giải']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '6', 'Leo', '', 'Kỷ luật công việc, chăm sóc sức khỏe và tinh thần phục vụ mang đặc đặc tính kiêu hãnh, tự tin và sáng tạo của Sư Tử. Bạn hoàn thành trách nhiệm hằng ngày một cách rực rỡ, hào phóng và cuốn hút.', 'Trong cuộc sống hằng ngày, vị trí Nhà 6 ở Sư Tử định hình phản ứng thực tế và cách bạn thể hiện bản thân. Even in routine tasks, you try to inject flair and leadership. You take great pride in your work and expect your efforts to be acknowledged and praised.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 6 và năng lượng Sư Tử: Charismatic leadership in the workplace, the ability to inspire coworkers, and a generous, warm approach to daily service.', 'Thách thức cần lưu ý: Arrogance, refusing to do "menial" tasks, dominating colleagues, and suffering health issues due to stress when your ego is bruised.', 'You expect loyalty and admiration from your coworkers. You are generous with your help but must be the recognized leader of the pack.', 'Learn that true service does not always require an audience. Find joy in doing a job well, even if no one is watching.', ARRAY['Nhà 6', 'Sư Tử']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '6', 'Virgo', '', 'Kỷ luật công việc, chăm sóc sức khỏe và tinh thần phục vụ mang đặc đặc tính tỉ mỉ, cẩn thận và thực tế của Xử Nữ. Bạn hoàn thành trách nhiệm hằng ngày một cách chỉn chu, phân tích và có phương pháp.', 'Trong cuộc sống hằng ngày, vị trí Nhà 6 ở Xử Nữ định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are the ultimate organizer. You excel at optimizing routines, analyzing data, and finding practical solutions to complex daily problems. You are highly conscious of health and diet.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 6 và năng lượng Xử Nữ: Unmatched analytical skills, meticulous attention to detail, a profound work ethic, and a genuine, humble desire to be of service.', 'Thách thức cần lưu ý: Extreme perfectionism, nitpicking coworkers, working yourself to the point of anxiety-induced illness, and never feeling like your work is "good enough."', 'You show you care by fixing things and organizing your colleagues. You demand competence and can be highly critical of lazy coworkers.', 'Learn to silence your inner critic. Accept that "good enough" is often perfect, and allow yourself time to rest without feeling guilty.', ARRAY['Nhà 6', 'Xử Nữ']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '6', 'Libra', '', 'Kỷ luật công việc, chăm sóc sức khỏe và tinh thần phục vụ mang đặc đặc tính hài hòa, lịch thiệp và công bằng của Thiên Bình. Bạn hoàn thành trách nhiệm hằng ngày một cách khéo léo, tinh tế và hướng tới sự cân bằng.', 'Trong cuộc sống hằng ngày, vị trí Nhà 6 ở Thiên Bình định hình phản ứng thực tế và cách bạn thể hiện bản thân. You excel in jobs requiring diplomacy, design, or collaboration. You strive to make your workspace beautiful and go out of your way to keep the peace among colleagues.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 6 và năng lượng Thiên Bình: Excellent mediation skills, a talent for creating a pleasant work atmosphere, and the ability to work beautifully in partnerships.', 'Thách thức cần lưu ý: Indecisiveness regarding daily tasks, avoiding necessary confrontations at work, and compromising your own health or boundaries to please others.', 'You view coworkers as partners and thrive in collaborative settings. You detest conflict and may struggle in a highly competitive workplace.', 'Do not sacrifice your own needs for the sake of artificial peace. Learn to assert yourself and handle healthy conflict in your daily life.', ARRAY['Nhà 6', 'Thiên Bình']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '6', 'Scorpio', '', 'Kỷ luật công việc, chăm sóc sức khỏe và tinh thần phục vụ mang đặc đặc tính sâu sắc, kiên cường và thâm trầm của Bọ Cạp. Bạn hoàn thành trách nhiệm hằng ngày một cách mãnh liệt, trực giác và bí ẩn.', 'Trong cuộc sống hằng ngày, vị trí Nhà 6 ở Bọ Cạp định hình phản ứng thực tế và cách bạn thể hiện bản thân. You dive deeply into your tasks, often preferring research, investigation, or crisis management. You are intensely private about your daily routines and have incredible physical resilience.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 6 và năng lượng Bọ Cạp: Unwavering focus, the ability to solve the most difficult problems, profound resourcefulness, and the capacity to regenerate your health after a crisis.', 'Thách thức cần lưu ý: Obsessive behavior at work, power struggles with colleagues, paranoia, and a tendency to hold onto stress until it physically manifests.', 'You are a formidable coworker who demands absolute dedication. You are fiercely loyal to trusted colleagues but ruthless if betrayed.', 'Learn to let go of the need to control every aspect of your work. Practice relaxation techniques to release the intense psychological pressure you put on yourself.', ARRAY['Nhà 6', 'Bọ Cạp']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '6', 'Sagittarius', '', 'Kỷ luật công việc, chăm sóc sức khỏe và tinh thần phục vụ mang đặc đặc tính phóng khoáng, lạc quan và yêu tự do của Nhân Mã. Bạn hoàn thành trách nhiệm hằng ngày một cách thẳng thắn, rộng mở và giàu lý tưởng.', 'Trong cuộc sống hằng ngày, vị trí Nhà 6 ở Nhân Mã định hình phản ứng thực tế và cách bạn thể hiện bản thân. You need a job that offers variety, travel, or the opportunity to teach. You approach daily tasks with enthusiasm but despise being bogged down by minute details.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 6 và năng lượng Nhân Mã: Visionary problem-solving, an infectious enthusiasm that uplifts coworkers, and the ability to see the "big picture" of any project.', 'Thách thức cần lưu ý: Overlooking crucial details, avoiding routine responsibilities, restlessness, and promising more than you can practically deliver in a day.', 'You are a jovial and inspiring colleague. You prefer a laid-back work environment and chafe under strict management or rigid schedules.', 'Cultivate discipline regarding the mundane details of life. Big visions require solid, practical execution to become reality.', ARRAY['Nhà 6', 'Nhân Mã']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '6', 'Capricorn', '', 'Kỷ luật công việc, chăm sóc sức khỏe và tinh thần phục vụ mang đặc đặc tính kỷ luật, trách nhiệm và thực tế của Ma Kết. Bạn hoàn thành trách nhiệm hằng ngày một cách kiên trì, bài bản và có tầm nhìn dài hạn.', 'Trong cuộc sống hằng ngày, vị trí Nhà 6 ở Ma Kết định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are highly organized, serious, and incredibly hardworking. You likely take on a managerial role naturally, ensuring that operations run with maximum efficiency.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 6 và năng lượng Ma Kết: Exceptional executive skills, unwavering reliability, the ability to handle massive workloads, and a strategic approach to daily problems.', 'Thách thức cần lưu ý: Workaholism, a tendency to view colleagues merely as tools for success, pessimism, and neglecting physical health in the pursuit of ambition.', 'You are a demanding but fair coworker or boss. You respect competence and authority, viewing work relationships through a professional, structured lens.', 'Remember that you are a human being, not a machine. Prioritize your physical and mental health, and learn to delegate tasks.', ARRAY['Nhà 6', 'Ma Kết']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '6', 'Aquarius', '', 'Kỷ luật công việc, chăm sóc sức khỏe và tinh thần phục vụ mang đặc đặc tính độc đáo, tiến bộ và hướng tới cộng đồng của Bảo Bình. Bạn hoàn thành trách nhiệm hằng ngày một cách đột phá, trí tuệ và phi truyền thống.', 'Trong cuộc sống hằng ngày, vị trí Nhà 6 ở Bảo Bình định hình phản ứng thực tế và cách bạn thể hiện bản thân. You likely use technology or inventive methods to streamline your routines. You chafe under traditional office rules and prefer a flexible, independent work structure.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 6 và năng lượng Bảo Bình: Brilliant originality in problem-solving, a humanitarian approach to service, and the ability to modernize outdated systems.', 'Thách thức cần lưu ý: Rebelling against standard procedures just to be contrary, emotional detachment from colleagues, and unpredictable work habits.', 'You view your coworkers as a community of equals. You are friendly but demand intellectual freedom and personal space in the workplace.', 'Learn to integrate your brilliant ideas within existing structures. Sometimes, standard procedures exist for a reason; learn to innovate without causing chaos.', ARRAY['Nhà 6', 'Bảo Bình']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '7', 'Taurus', '', 'Mối quan hệ đối tác, tình cảm và sự hợp tác được định hình bởi năng lượng kiên định, bền bỉ và thực tế của Kim Ngưu. Bạn tìm kiếm sự cân bằng và đồng hành vững chắc, cẩn trọng và coi trọng chất lượng.', 'Trong cuộc sống hằng ngày, vị trí Nhà 7 ở Kim Ngưu định hình phản ứng thực tế và cách bạn thể hiện bản thân. You take your time before committing to someone. Once you do, you expect the relationship to last forever and provide a solid foundation of comfort and financial security.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 7 và năng lượng Kim Ngưu: Unwavering loyalty, the ability to build a deeply comfortable and secure life with a partner, and immense patience in resolving relationship issues.', 'Thách thức cần lưu ý: Stubbornness during disagreements, staying in unhealthy relationships out of a fear of change, and a tendency toward possessiveness or jealousy.', 'You express love through physical affection and providing for your partner. You require a relationship that feels absolutely secure and predictable.', 'Embrace the fact that relationships must evolve to survive. Do not confuse emotional stagnation with stability.', ARRAY['Nhà 7', 'Kim Ngưu']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '7', 'Gemini', '', 'Mối quan hệ đối tác, tình cảm và sự hợp tác được định hình bởi năng lượng nhanh trí, linh hoạt và tò mò của Song Tử. Bạn tìm kiếm sự cân bằng và đồng hành cởi mở, đa dạng và giỏi giao tiếp.', 'Trong cuộc sống hằng ngày, vị trí Nhà 7 ở Song Tử định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are drawn to witty, intelligent, and talkative partners. Your ideal relationship involves constant dialogue, shared learning, and a lighthearted approach to life.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 7 và năng lượng Song Tử: Exceptional communication skills within the partnership, the ability to keep the relationship youthful and fun, and a rational approach to solving relationship conflicts.', 'Thách thức cần lưu ý: Fickleness, a fear of deep emotional enmeshment, intellectualizing relationship problems rather than feeling them, and easily becoming bored with your partner.', 'You need absolute freedom to socialize and communicate outside the relationship. Clinginess or silence will quickly drive you away.', 'Strive for emotional depth as well as intellectual connection. A true partnership requires sharing vulnerabilities, not just exchanging information.', ARRAY['Nhà 7', 'Song Tử']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '7', 'Leo', '', 'Mối quan hệ đối tác, tình cảm và sự hợp tác được định hình bởi năng lượng kiêu hãnh, tự tin và sáng tạo của Sư Tử. Bạn tìm kiếm sự cân bằng và đồng hành rực rỡ, hào phóng và cuốn hút.', 'Trong cuộc sống hằng ngày, vị trí Nhà 7 ở Sư Tử định hình phản ứng thực tế và cách bạn thể hiện bản thân. You treat romance like a grand performance. You want a partner whom you can be proud of, and you expect to be treated like royalty in return.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 7 và năng lượng Sư Tử: Immense generosity toward your partner, unwavering loyalty, a passionate and warm approach to love, and the ability to fiercely defend your relationship.', 'Thách thức cần lưu ý: Dominating the partnership, a constant need for praise and validation from your partner, and allowing ego or pride to prevent necessary apologies.', 'You require a relationship filled with romance, grand gestures, and mutual respect. You despise petty squabbles and demand loyalty above all else.', 'Learn to share the stage. A truly regal partnership involves elevating your partner just as much as they elevate you.', ARRAY['Nhà 7', 'Sư Tử']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '7', 'Libra', '', 'Mối quan hệ đối tác, tình cảm và sự hợp tác được định hình bởi năng lượng hài hòa, lịch thiệp và công bằng của Thiên Bình. Bạn tìm kiếm sự cân bằng và đồng hành khéo léo, tinh tế và hướng tới sự cân bằng.', 'Trong cuộc sống hằng ngày, vị trí Nhà 7 ở Thiên Bình định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are a natural romantic and may feel incomplete without a partner. You are drawn to charming, diplomatic individuals and strive to maintain total peace in the relationship.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 7 và năng lượng Thiên Bình: Exceptional diplomacy and mediation skills, a deep dedication to fairness in the partnership, and the ability to create a beautifully romantic atmosphere.', 'Thách thức cần lưu ý: Codependency, losing your own identity to please your partner, avoiding necessary conflicts which leads to built-up resentment, and indecisiveness.', 'You require absolute equality and harmony. You hate ugly confrontations and will often sacrifice your own needs just to keep the relationship stable.', 'Develop a strong sense of self independent of any partnership. Realize that healthy conflict is necessary to build a truly robust relationship.', ARRAY['Nhà 7', 'Thiên Bình']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '7', 'Sagittarius', '', 'Mối quan hệ đối tác, tình cảm và sự hợp tác được định hình bởi năng lượng phóng khoáng, lạc quan và yêu tự do của Nhân Mã. Bạn tìm kiếm sự cân bằng và đồng hành thẳng thắn, rộng mở và giàu lý tưởng.', 'Trong cuộc sống hằng ngày, vị trí Nhà 7 ở Nhân Mã định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are drawn to individuals from different cultures or backgrounds. You need a relationship that offers constant growth, travel, and intellectual exploration rather than domestic routine.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 7 và năng lượng Nhân Mã: An optimistic and joyous approach to love, the ability to inspire your partner, and maintaining a healthy sense of independence within the relationship.', 'Thách thức cần lưu ý: Fear of commitment, restlessness, overlooking the practical realities of a partnership, and a lack of tact that can unintentionally hurt your partner.', 'You require massive amounts of personal space and freedom. A clingy or overly domestic partner will make you feel trapped and eager to escape.', 'Learn that commitment does not equal imprisonment. Cultivate the discipline to stay present during the mundane, unadventurous parts of the relationship.', ARRAY['Nhà 7', 'Nhân Mã']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '7', 'Capricorn', '', 'Mối quan hệ đối tác, tình cảm và sự hợp tác được định hình bởi năng lượng kỷ luật, trách nhiệm và thực tế của Ma Kết. Bạn tìm kiếm sự cân bằng và đồng hành kiên trì, bài bản và có tầm nhìn dài hạn.', 'Trong cuộc sống hằng ngày, vị trí Nhà 7 ở Ma Kết định hình phản ứng thực tế và cách bạn thể hiện bản thân. You do not rush into commitments. You view marriage almost as a business partnership, aiming to build a solid legacy and social status alongside your spouse.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 7 và năng lượng Ma Kết: Exceptional reliability, a steadfast commitment to the vows you make, providing immense material security, and acting as a rock for your partner.', 'Thách thức cần lưu ý: Emotional coldness, treating the relationship like a transaction, a fear of vulnerability, and prioritizing work or status over romance.', 'You express love through duty and provision. You need a partner who understands the value of hard work and respects traditional relationship roles.', 'Allow yourself to be emotionally vulnerable with your partner. A successful marriage requires emotional warmth and romance just as much as financial security.', ARRAY['Nhà 7', 'Ma Kết']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '7', 'Aquarius', '', 'Mối quan hệ đối tác, tình cảm và sự hợp tác được định hình bởi năng lượng độc đáo, tiến bộ và hướng tới cộng đồng của Bảo Bình. Bạn tìm kiếm sự cân bằng và đồng hành đột phá, trí tuệ và phi truyền thống.', 'Trong cuộc sống hằng ngày, vị trí Nhà 7 ở Bảo Bình định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are drawn to eccentric or brilliant individuals. Your ideal relationship defies traditional norms, often feeling more like a partnership of two independent best friends.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 7 và năng lượng Bảo Bình: Tolerance, open-mindedness, a refusal to control or restrict your partner, and a highly intellectual approach to resolving relationship issues.', 'Thách thức cần lưu ý: Emotional detachment, unpredictability, a fear of deep, messy emotional intimacy, and rebelling against commitment just to maintain your independence.', 'You require absolute intellectual freedom and personal space. You despise traditional, restrictive relationship roles and need a partner who is also your intellectual equal.', 'Learn to connect on a deep emotional level, not just an intellectual one. True intimacy requires showing your heart, not just your brilliant mind.', ARRAY['Nhà 7', 'Bảo Bình']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '8', 'Taurus', '', 'Sức mạnh chuyển hóa, tài chính chung và sự gắn kết sâu sắc mang chiều sâu kiên định, bền bỉ và thực tế của Kim Ngưu. Bạn đối mặt với biến chuyển cuộc sống một cách vững chắc, cẩn trọng và coi trọng chất lượng.', 'Trong cuộc sống hằng ngày, vị trí Nhà 8 ở Kim Ngưu định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are cautious about sharing resources or merging intimately. Once you do, you expect the bond to be unbreakable. You may gain financially through partnerships or inheritances.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 8 và năng lượng Kim Ngưu: Incredible endurance during psychological crises, a talent for managing and growing joint finances, and a deeply grounded, sensual approach to intimacy.', 'Thách thức cần lưu ý: Extreme stubbornness when faced with necessary transformation, hoarding shared resources out of fear, and intense possessiveness or jealousy in intimate relationships.', 'You require absolute material and emotional security before you will truly merge with someone. You express deep intimacy through physical touch and provision.', 'Learn to let go. True transformation requires releasing your grip on what you think makes you secure. Embrace the inevitable changes of life.', ARRAY['Nhà 8', 'Kim Ngưu']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '8', 'Cancer', '', 'Sức mạnh chuyển hóa, tài chính chung và sự gắn kết sâu sắc mang chiều sâu nhạy cảm, thấu cảm và chu đáo của Cự Giải. Bạn đối mặt với biến chuyển cuộc sống một cách ấm áp, bảo vệ và giàu tình cảm.', 'Trong cuộc sống hằng ngày, vị trí Nhà 8 ở Cự Giải định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are highly sensitive to the psychological currents around you. You are fiercely protective of your shared resources and require immense emotional trust before allowing anyone into your inner sanctum.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 8 và năng lượng Cự Giải: Profound psychological intuition, the ability to heal the deep emotional wounds of others, and an incredible capacity for soulful, nurturing intimacy.', 'Thách thức cần lưu ý: Clinging desperately to past traumas, a fear of letting go of toxic relationships due to emotional attachment, and using guilt to manipulate intimate partners.', 'You seek a bond that feels like a return to the womb—safe, warm, and completely unified. Any breach of trust in this area is deeply devastating to you.', 'Learn to release past hurts and forgive. Do not let your fear of abandonment prevent you from undergoing necessary personal transformations.', ARRAY['Nhà 8', 'Cự Giải']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '8', 'Leo', '', 'Sức mạnh chuyển hóa, tài chính chung và sự gắn kết sâu sắc mang chiều sâu kiêu hãnh, tự tin và sáng tạo của Sư Tử. Bạn đối mặt với biến chuyển cuộc sống một cách rực rỡ, hào phóng và cuốn hút.', 'Trong cuộc sống hằng ngày, vị trí Nhà 8 ở Sư Tử định hình phản ứng thực tế và cách bạn thể hiện bản thân. You approach joint finances and intimate relationships with generosity and a desire for control. You may gain wealth through a partner but expect to be recognized for your contribution to the shared pot.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 8 và năng lượng Sư Tử: Immense courage and dignity during times of crisis, a deeply passionate and warm approach to intimacy, and the ability to bring light to dark psychological spaces.', 'Thách thức cần lưu ý: Arrogance regarding joint resources, a refusal to admit vulnerability or weakness, and a tendency to turn intimate conflicts into dramatic ego clashes.', 'You demand fierce loyalty and adoration in your most intimate bonds. You want to be proud of the person you merge with and expect them to treat you as their ultimate treasure.', 'Learn to put your pride aside. True intimacy requires admitting your flaws and vulnerabilities without fearing that you will lose your dignity.', ARRAY['Nhà 8', 'Sư Tử']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '8', 'Libra', '', 'Sức mạnh chuyển hóa, tài chính chung và sự gắn kết sâu sắc mang chiều sâu hài hòa, lịch thiệp và công bằng của Thiên Bình. Bạn đối mặt với biến chuyển cuộc sống một cách khéo léo, tinh tế và hướng tới sự cân bằng.', 'Trong cuộc sống hằng ngày, vị trí Nhà 8 ở Thiên Bình định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are highly diplomatic when dealing with shared resources and strive for absolute fairness in joint finances. You desire an intimate relationship that is both profound and peaceful.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 8 và năng lượng Thiên Bình: Excellent mediation skills during crises, the ability to create harmony in deeply intimate spaces, and a refined, romantic approach to profound psychological bonding.', 'Thách thức cần lưu ý: Avoiding necessary deep psychological confrontations to keep the peace, indecisiveness regarding joint finances, and codependency in intimate relationships.', 'You view deep intimacy as the ultimate partnership. You loathe ugly emotional outbursts and may suppress your own dark feelings to maintain a beautiful facade.', 'Do not be afraid of the "ugly" side of human nature. True transformation requires facing the darkness, and true intimacy requires absolute honesty, even when it is not peaceful.', ARRAY['Nhà 8', 'Thiên Bình']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '8', 'Scorpio', '', 'Sức mạnh chuyển hóa, tài chính chung và sự gắn kết sâu sắc mang chiều sâu sâu sắc, kiên cường và thâm trầm của Bọ Cạp. Bạn đối mặt với biến chuyển cuộc sống một cách mãnh liệt, trực giác và bí ẩn.', 'Trong cuộc sống hằng ngày, vị trí Nhà 8 ở Bọ Cạp định hình phản ứng thực tế và cách bạn thể hiện bản thân. This is the natural home of Scorpio. You possess profound psychological depth, a fascination with the occult or the mysteries of death, and a demand for absolute, soul-consuming intimacy.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 8 và năng lượng Bọ Cạp: Unmatched psychological resilience, the ability to regenerate completely after a crisis, profound insight into the motives of others, and intense, transformative passion.', 'Thách thức cần lưu ý: Paranoia, an obsessive need for control in intimate relationships, holding onto deep-seated resentments, and a tendency toward destructive power struggles.', 'You demand total transparency, absolute loyalty, and complete emotional merging. You are fiercely protective of your shared resources and intimate secrets.', 'Learn to forgive and let go. Your immense power must be used for healing, not for control or revenge. Trust that vulnerability is your greatest strength.', ARRAY['Nhà 8', 'Bọ Cạp']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '8', 'Capricorn', '', 'Sức mạnh chuyển hóa, tài chính chung và sự gắn kết sâu sắc mang chiều sâu kỷ luật, trách nhiệm và thực tế của Ma Kết. Bạn đối mặt với biến chuyển cuộc sống một cách kiên trì, bài bản và có tầm nhìn dài hạn.', 'Trong cuộc sống hằng ngày, vị trí Nhà 8 ở Ma Kết định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are highly responsible with joint finances, taxes, and inheritances. You do not merge intimately easily, requiring a long time to build the necessary trust and structure for a deep bond.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 8 và năng lượng Ma Kết: Exceptional reliability in managing shared assets, a stoic resilience during crises, and a deep, enduring commitment once you finally choose to merge with someone.', 'Thách thức cần lưu ý: Emotional coldness in intimate spaces, a fear of vulnerability that prevents true merging, treating joint resources purely as a business transaction, and deep-seated pessimism.', 'You express deep intimacy by taking on responsibility for your partner. You need a structured, predictable environment to feel safe enough to reveal your hidden depths.', 'Allow yourself to surrender control. Intimacy is not a business contract; it requires emotional warmth and the courage to be completely vulnerable without a safety net.', ARRAY['Nhà 8', 'Ma Kết']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '8', 'Aquarius', '', 'Sức mạnh chuyển hóa, tài chính chung và sự gắn kết sâu sắc mang chiều sâu độc đáo, tiến bộ và hướng tới cộng đồng của Bảo Bình. Bạn đối mặt với biến chuyển cuộc sống một cách đột phá, trí tuệ và phi truyền thống.', 'Trong cuộc sống hằng ngày, vị trí Nhà 8 ở Bảo Bình định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are fascinated by psychology but approach it scientifically rather than emotionally. You prefer unconventional arrangements for shared resources and require immense personal space in intimate relationships.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 8 và năng lượng Bảo Bình: Brilliant, objective insight into human psychology, the ability to detach and remain calm during a crisis, and an open-minded, tolerant approach to intimacy.', 'Thách thức cần lưu ý: Extreme emotional detachment that frustrates intimate partners, rebelling against deep commitment, and an inability to handle the messy, irrational nature of human trauma.', 'You view intimate partners as friends and equals. You despise possessiveness or jealousy and demand that your individual freedom be respected, even when deeply merged.', 'Learn to connect with the raw, irrational emotions of the heart. Intellectualizing trauma or intimacy prevents true, profound psychological transformation.', ARRAY['Nhà 8', 'Bảo Bình']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '8', 'Pisces', '', 'Sức mạnh chuyển hóa, tài chính chung và sự gắn kết sâu sắc mang chiều sâu mềm mại, vị tha và sâu sắc của Song Ngư. Bạn đối mặt với biến chuyển cuộc sống một cách thấu cảm, lãng mạn và giàu trí tưởng tượng.', 'Trong cuộc sống hằng ngày, vị trí Nhà 8 ở Song Ngư định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are incredibly sensitive to the psychological energies around you. You approach joint finances with a fluid, generous attitude and seek an intimate bond that transcends the physical realm.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 8 và năng lượng Song Ngư: Profound spiritual insight into life and death, immense compassion for the trauma of others, and the ability to heal deeply through unconditional love and mystical intimacy.', 'Thách thức cần lưu ý: A lack of boundaries that leads to being taken advantage of financially or emotionally, getting lost in illusions, and taking on the psychological burdens of others.', 'You seek absolute spiritual fusion. You are highly adaptable in intimate settings but must guard against toxic individuals who may drain your immense energetic resources.', 'Establish iron-clad boundaries regarding your shared resources and your emotional energy. Learn to protect yourself so that your profound compassion is not exploited.', ARRAY['Nhà 8', 'Song Ngư']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '9', 'Aries', '', 'Tầm nhìn triết lý, tri thức mở rộng và tinh thần khám phá phát triển qua lăng kính tiên phong, quyết đoán và độc lập của Bạch Dương. Bạn vươn tới mục tiêu cao đẹp một cách trực diện, dũng cảm và nhiệt huyết.', 'Trong cuộc sống hằng ngày, vị trí Nhà 9 ở Bạch Dương định hình phản ứng thực tế và cách bạn thể hiện bản thân. You love to travel spontaneously and seek out adventurous, active experiences abroad. Your belief system is strong, and you will fiercely defend your philosophical or religious views.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 9 và năng lượng Bạch Dương: Courage to explore the unknown, an inspiring and energetic approach to teaching or learning, and the ability to initiate grand, visionary projects.', 'Thách thức cần lưu ý: Dogmatism, a tendency to argue aggressively over beliefs, impulsiveness in travel plans, and lacking the patience for long, structured academic studies.', 'You are an independent thinker who dislikes being told what to believe. You inspire others with your bold visions but can be impatient with those who learn slower than you.', 'Cultivate patience and respect for differing viewpoints. Learn that true wisdom often involves listening to others, not just conquering debates.', ARRAY['Nhà 9', 'Bạch Dương']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '9', 'Taurus', '', 'Tầm nhìn triết lý, tri thức mở rộng và tinh thần khám phá phát triển qua lăng kính kiên định, bền bỉ và thực tế của Kim Ngưu. Bạn vươn tới mục tiêu cao đẹp một cách vững chắc, cẩn trọng và coi trọng chất lượng.', 'Trong cuộc sống hằng ngày, vị trí Nhà 9 ở Kim Ngưu định hình phản ứng thực tế và cách bạn thể hiện bản thân. You prefer to travel in comfort and enjoy experiencing the physical beauty and food of different cultures. You learn best through practical application and hold fast to traditional or proven philosophies.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 9 và năng lượng Kim Ngưu: Steadfast dedication to higher learning, the ability to build practical structures based on grand philosophies, and a deeply grounded, sensual appreciation of the world.', 'Thách thức cần lưu ý: Extreme stubbornness regarding your beliefs, a refusal to explore abstract concepts that lack tangible proof, and a reluctance to travel outside your comfort zone.', 'You build your life philosophy slowly and rarely change it. You provide a stabilizing influence for others, showing them how to ground their grand ideas in reality.', 'Open your mind to the abstract and the unknown. Understand that just because something cannot be touched does not mean it lacks profound value.', ARRAY['Nhà 9', 'Kim Ngưu']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '9', 'Gemini', '', 'Tầm nhìn triết lý, tri thức mở rộng và tinh thần khám phá phát triển qua lăng kính nhanh trí, linh hoạt và tò mò của Song Tử. Bạn vươn tới mục tiêu cao đẹp một cách cởi mở, đa dạng và giỏi giao tiếp.', 'Trong cuộc sống hằng ngày, vị trí Nhà 9 ở Song Tử định hình phản ứng thực tế và cách bạn thể hiện bản thân. You love to gather information from diverse cultures, religions, and philosophies. You prefer short, frequent trips to long, arduous journeys and enjoy discussing your findings with everyone.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 9 và năng lượng Song Tử: Exceptional versatility in learning, a brilliant and inquisitive mind, the ability to communicate complex philosophies clearly, and a tolerant, open-minded worldview.', 'Thách thức cần lưu ý: Superficial understanding of complex subjects, a short attention span that prevents deep academic mastery, and changing your beliefs too frequently based on the latest trend.', 'You thrive in academic or travel environments that offer constant conversation and new data. You are a fascinating teacher who keeps students constantly engaged.', 'Learn to focus your mind and dive deeply into a single subject. Breadth of knowledge is wonderful, but depth of understanding is necessary for true wisdom.', ARRAY['Nhà 9', 'Song Tử']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '9', 'Leo', '', 'Tầm nhìn triết lý, tri thức mở rộng và tinh thần khám phá phát triển qua lăng kính kiêu hãnh, tự tin và sáng tạo của Sư Tử. Bạn vươn tới mục tiêu cao đẹp một cách rực rỡ, hào phóng và cuốn hút.', 'Trong cuộc sống hằng ngày, vị trí Nhà 9 ở Sư Tử định hình phản ứng thực tế và cách bạn thể hiện bản thân. You love to travel in style and experience the grandeur of the world. You hold your beliefs with passionate conviction and love to share your wisdom with an audience.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 9 và năng lượng Sư Tử: Charismatic teaching abilities, a generous and inspiring worldview, immense creative vision, and the courage to stand proudly by your philosophical convictions.', 'Thách thức cần lưu ý: Intellectual arrogance, dogmatism, a need to be admired for your intellect, and a refusal to admit when your beliefs are wrong.', 'You expect respect for your intellect and worldview. You are a natural leader in academic or religious settings, capable of inspiring large groups of people.', 'Learn the virtue of intellectual humility. True wisdom requires recognizing how much you do not know and being willing to learn from those you consider your subordinates.', ARRAY['Nhà 9', 'Sư Tử']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '9', 'Virgo', '', 'Tầm nhìn triết lý, tri thức mở rộng và tinh thần khám phá phát triển qua lăng kính tỉ mỉ, cẩn thận và thực tế của Xử Nữ. Bạn vươn tới mục tiêu cao đẹp một cách chỉn chu, phân tích và có phương pháp.', 'Trong cuộc sống hằng ngày, vị trí Nhà 9 ở Xử Nữ định hình phản ứng thực tế và cách bạn thể hiện bản thân. You excel in academic environments due to your meticulous attention to detail. You prefer purposeful travel, such as work trips or educational tours, rather than idle vacations.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 9 và năng lượng Xử Nữ: Exceptional research skills, a brilliant analytical mind, the ability to organize complex philosophical systems, and a humble dedication to higher learning.', 'Thách thức cần lưu ý: Getting lost in minor academic details while missing the big picture, over-analyzing belief systems until they lose their meaning, and extreme criticism of differing views.', 'You approach the search for meaning as a puzzle to be solved. You are a highly effective, though demanding, teacher who insists on accuracy and practical application.', 'Learn to step back and look at the forest, not just the trees. Allow yourself to experience the awe and mystery of the world without needing to categorize it immediately.', ARRAY['Nhà 9', 'Xử Nữ']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '9', 'Libra', '', 'Tầm nhìn triết lý, tri thức mở rộng và tinh thần khám phá phát triển qua lăng kính hài hòa, lịch thiệp và công bằng của Thiên Bình. Bạn vươn tới mục tiêu cao đẹp một cách khéo léo, tinh tế và hướng tới sự cân bằng.', 'Trong cuộc sống hằng ngày, vị trí Nhà 9 ở Thiên Bình định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are drawn to studying law, art, or sociology. You prefer traveling with a partner and seek out culturally refined, beautiful destinations. Your worldview is built on diplomacy.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 9 và năng lượng Thiên Bình: A deeply fair and objective worldview, the ability to see multiple sides of a philosophical debate, and a talent for promoting peace and cultural understanding.', 'Thách thức cần lưu ý: Indecisiveness regarding your own core beliefs, adopting the philosophies of your partner to avoid conflict, and a tendency to prioritize aesthetics over hard truths.', 'You thrive in academic or travel settings where you can collaborate. You are an excellent mediator who uses your higher knowledge to bring people together.', 'Do not be afraid to take a firm stand on a philosophical issue, even if it causes conflict. True justice sometimes requires disrupting the peace.', ARRAY['Nhà 9', 'Thiên Bình']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '9', 'Scorpio', '', 'Tầm nhìn triết lý, tri thức mở rộng và tinh thần khám phá phát triển qua lăng kính sâu sắc, kiên cường và thâm trầm của Bọ Cạp. Bạn vươn tới mục tiêu cao đẹp một cách mãnh liệt, trực giác và bí ẩn.', 'Trong cuộc sống hằng ngày, vị trí Nhà 9 ở Bọ Cạp định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are fascinated by the occult, psychology, or the mysteries of life and death. You prefer travel that completely transforms you, perhaps visiting intense or historically significant locations.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 9 và năng lượng Bọ Cạp: Profound insight into the hidden truths of the universe, unwavering focus in academic research, and the ability to completely regenerate your worldview after a crisis.', 'Thách thức cần lưu ý: Dogmatic obsession with your beliefs, paranoia regarding foreign cultures or differing philosophies, and using your knowledge to manipulate or control others.', 'You are a formidable student and teacher, demanding absolute depth and honesty. You despise superficial philosophies and will relentlessly question accepted dogmas.', 'Use your penetrating insight to heal and transform, not to destroy. Learn to trust that the universe is not always a dark, secretive place; there is light to be found as well.', ARRAY['Nhà 9', 'Bọ Cạp']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '9', 'Capricorn', '', 'Tầm nhìn triết lý, tri thức mở rộng và tinh thần khám phá phát triển qua lăng kính kỷ luật, trách nhiệm và thực tế của Ma Kết. Bạn vươn tới mục tiêu cao đẹp một cách kiên trì, bài bản và có tầm nhìn dài hạn.', 'Trong cuộc sống hằng ngày, vị trí Nhà 9 ở Ma Kết định hình phản ứng thực tế và cách bạn thể hiện bản thân. You take your education very seriously, often viewing it as a stepping stone to career advancement. You prefer organized, purposeful travel and hold conservative or highly pragmatic beliefs.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 9 và năng lượng Ma Kết: Exceptional academic discipline, the ability to master complex subjects through hard work, strategic long-term planning, and a deep respect for traditional wisdom.', 'Thách thức cần lưu ý: Pessimism, mental rigidity, dismissing abstract or spiritual philosophies as useless, and treating higher learning purely as a business transaction.', 'You are an authoritative figure in your chosen field of study. You respect established institutions and prefer to build your worldview on solid, proven facts rather than theories.', 'Open your mind to the abstract and the spiritual. Understand that not all valuable knowledge results in immediate material success or social status.', ARRAY['Nhà 9', 'Ma Kết']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '9', 'Aquarius', '', 'Tầm nhìn triết lý, tri thức mở rộng và tinh thần khám phá phát triển qua lăng kính độc đáo, tiến bộ và hướng tới cộng đồng của Bảo Bình. Bạn vươn tới mục tiêu cao đẹp một cách đột phá, trí tuệ và phi truyền thống.', 'Trong cuộc sống hằng ngày, vị trí Nhà 9 ở Bảo Bình định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are drawn to studying science, technology, or progressive sociology. You prefer traveling off the beaten path and hold highly original, sometimes eccentric, philosophical views.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 9 và năng lượng Bảo Bình: Brilliant originality in thought, a deeply objective and tolerant worldview, the ability to grasp futuristic concepts, and a dedication to collective human progress.', 'Thách thức cần lưu ý: Intellectual superiority, extreme stubbornness regarding your unique views, rebelling against traditional education just to be contrary, and emotional detachment from your beliefs.', 'You view the world as a global community. You are a fascinating, forward-thinking teacher who encourages students to question everything and think outside the box.', 'Learn to integrate emotional intelligence into your brilliant worldview. Remember that humanity is driven by the heart just as much as by the mind.', ARRAY['Nhà 9', 'Bảo Bình']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '9', 'Pisces', '', 'Tầm nhìn triết lý, tri thức mở rộng và tinh thần khám phá phát triển qua lăng kính mềm mại, vị tha và sâu sắc của Song Ngư. Bạn vươn tới mục tiêu cao đẹp một cách thấu cảm, lãng mạn và giàu trí tưởng tượng.', 'Trong cuộc sống hằng ngày, vị trí Nhà 9 ở Song Ngư định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are drawn to studying mysticism, art, or healing. You prefer travel that feels like a spiritual pilgrimage or an escape from reality. Your beliefs are rooted in universal compassion.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 9 và năng lượng Song Ngư: Profound spiritual insight, an incredible imagination that grasps abstract concepts effortlessly, boundless empathy for different cultures, and visionary inspiration.', 'Thách thức cần lưu ý: Mental confusion, a lack of focus in academic settings, getting lost in illusions or cult-like philosophies, and struggling to articulate your profound visions logically.', 'You absorb knowledge osmotically rather than through rigid study. You are a deeply compassionate teacher who seeks to uplift the souls of your students.', 'Ground your mystical visions in logical structure. Develop the discipline to study effectively and learn to clearly articulate your spiritual insights so others can benefit from them.', ARRAY['Nhà 9', 'Song Ngư']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '10', 'Aries', '', 'Sự nghiệp, uy tín xã hội và mục tiêu dài hạn phản ánh bản lĩnh tiên phong, quyết đoán và độc lập của Bạch Dương. Bạn xây dựng chỗ đứng và danh tiếng một cách trực diện, dũng cảm và nhiệt huyết.', 'Trong cuộc sống hằng ngày, vị trí Nhà 10 ở Bạch Dương định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are highly competitive in your professional life. You likely forge your own path, preferring entrepreneurship or leadership roles over taking orders.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 10 và năng lượng Bạch Dương: Fearless ambition, the ability to initiate major professional projects, natural executive presence, and a courageous public image.', 'Thách thức cần lưu ý: Impatience with career progression, conflict with authority figures, a tendency to quit when bored, and coming across as overly aggressive in public.', 'You need a partner who supports your intense ambitions and understands that your career is a battlefield you intend to conquer.', 'Learn that true leadership involves guiding others, not just conquering them. Cultivate patience for the long-term grind of career building.', ARRAY['Nhà 10', 'Bạch Dương']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '10', 'Taurus', '', 'Sự nghiệp, uy tín xã hội và mục tiêu dài hạn phản ánh bản lĩnh kiên định, bền bỉ và thực tế của Kim Ngưu. Bạn xây dựng chỗ đứng và danh tiếng một cách vững chắc, cẩn trọng và coi trọng chất lượng.', 'Trong cuộc sống hằng ngày, vị trí Nhà 10 ở Kim Ngưu định hình phản ứng thực tế và cách bạn thể hiện bản thân. You climb the career ladder slowly but steadily. You prefer established, secure industries (like finance, real estate, or agriculture) and project a calm, unshakable public persona.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 10 và năng lượng Kim Ngưu: Unwavering professional endurance, the ability to manage massive projects over long periods, and an excellent reputation for producing high-quality work.', 'Thách thức cần lưu ý: Stubborn resistance to changing career paths, staying in unfulfilling jobs purely for financial security, and a fear of taking professional risks.', 'You view your career as a means to provide for your family. You need a partner who values your steady ambition and respects your need for a predictable work life.', 'Embrace innovation in your career. Understand that taking calculated risks is sometimes necessary to achieve true professional greatness.', ARRAY['Nhà 10', 'Kim Ngưu']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '10', 'Gemini', '', 'Sự nghiệp, uy tín xã hội và mục tiêu dài hạn phản ánh bản lĩnh nhanh trí, linh hoạt và tò mò của Song Tử. Bạn xây dựng chỗ đứng và danh tiếng một cách cởi mở, đa dạng và giỏi giao tiếp.', 'Trong cuộc sống hằng ngày, vị trí Nhà 10 ở Song Tử định hình phản ứng thực tế và cách bạn thể hiện bản thân. You likely have multiple careers simultaneously or work in fields requiring constant communication (writing, speaking, sales, media). Your public image is youthful and dynamic.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 10 và năng lượng Song Tử: Exceptional networking skills, the ability to adapt instantly to changing professional landscapes, and a talent for communicating complex ideas to the public.', 'Thách thức cần lưu ý: Career restlessness, a lack of deep focus that prevents you from reaching the absolute top of a single field, and a reputation for being somewhat scattered.', 'You need a partner who can keep up with your fast-paced public life and understands that your career requires constant socializing.', 'Develop professional discipline. Pick one or two primary fields and dedicate yourself to mastering them deeply rather than skimming the surface of many.', ARRAY['Nhà 10', 'Song Tử']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '10', 'Virgo', '', 'Sự nghiệp, uy tín xã hội và mục tiêu dài hạn phản ánh bản lĩnh tỉ mỉ, cẩn thận và thực tế của Xử Nữ. Bạn xây dựng chỗ đứng và danh tiếng một cách chỉn chu, phân tích và có phương pháp.', 'Trong cuộc sống hằng ngày, vị trí Nhà 10 ở Xử Nữ định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are highly modest about your achievements, preferring to work quietly behind the scenes. You excel in fields requiring precision, analysis, or healthcare.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 10 và năng lượng Xử Nữ: Unmatched professional competence, a relentless work ethic, brilliant problem-solving skills, and a pristine reputation for reliability and accuracy.', 'Thách thức cần lưu ý: Extreme perfectionism that delays career progress, a tendency to accept subordinate roles despite having the skills to lead, and crippling self-criticism.', 'You view your career as your primary duty. You need a partner who respects your long hours and understands that you express love through practical achievement.', 'Learn to accept praise for your hard work and do not be afraid to step into leadership roles. Silence your inner critic and recognize your immense professional value.', ARRAY['Nhà 10', 'Xử Nữ']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '10', 'Libra', '', 'Sự nghiệp, uy tín xã hội và mục tiêu dài hạn phản ánh bản lĩnh hài hòa, lịch thiệp và công bằng của Thiên Bình. Bạn xây dựng chỗ đứng và danh tiếng một cách khéo léo, tinh tế và hướng tới sự cân bằng.', 'Trong cuộc sống hằng ngày, vị trí Nhà 10 ở Thiên Bình định hình phản ứng thực tế và cách bạn thể hiện bản thân. You excel in fields requiring mediation, law, art, or public relations. You have a highly refined public image and strive to maintain excellent relationships with authority figures.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 10 và năng lượng Thiên Bình: Exceptional diplomacy in the workplace, a talent for creating beautiful or harmonious public works, and the ability to navigate complex professional politics effortlessly.', 'Thách thức cần lưu ý: Indecisiveness regarding your career path, compromising your own professional goals to please bosses or partners, and a fear of making unpopular executive decisions.', 'You often prefer to work in business partnerships rather than alone. You need a supportive spouse to feel truly balanced in your public life.', 'Develop the courage to stand alone professionally. Learn that true leadership sometimes requires making decisions that will temporarily disrupt the peace.', ARRAY['Nhà 10', 'Thiên Bình']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '10', 'Scorpio', '', 'Sự nghiệp, uy tín xã hội và mục tiêu dài hạn phản ánh bản lĩnh sâu sắc, kiên cường và thâm trầm của Bọ Cạp. Bạn xây dựng chỗ đứng và danh tiếng một cách mãnh liệt, trực giác và bí ẩn.', 'Trong cuộc sống hằng ngày, vị trí Nhà 10 ở Bọ Cạp định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are drawn to careers involving investigation, psychology, crisis management, or hidden resources. You guard your public reputation fiercely and possess a magnetic, intimidating authority.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 10 và năng lượng Bọ Cạp: Incredible resilience in overcoming career setbacks, the ability to wield immense professional power, and profound insight into the hidden dynamics of your industry.', 'Thách thức cần lưu ý: Paranoia regarding colleagues or competitors, an obsessive need for control that alienates others, and a tendency to engage in ruthless professional power struggles.', 'You are intensely private about your career ambitions. You demand absolute loyalty from business partners and will quickly cut ties if betrayed.', 'Use your immense professional power to heal and transform your industry, not just to control it. Learn to trust your colleagues and delegate authority.', ARRAY['Nhà 10', 'Bọ Cạp']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '10', 'Sagittarius', '', 'Sự nghiệp, uy tín xã hội và mục tiêu dài hạn phản ánh bản lĩnh phóng khoáng, lạc quan và yêu tự do của Nhân Mã. Bạn xây dựng chỗ đứng và danh tiếng một cách thẳng thắn, rộng mở và giàu lý tưởng.', 'Trong cuộc sống hằng ngày, vị trí Nhà 10 ở Nhân Mã định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are known for your visionary ideas and infectious enthusiasm. You likely work in fields involving higher education, publishing, international business, or travel.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 10 và năng lượng Nhân Mã: Boundless professional optimism, the ability to inspire massive audiences, a global perspective on your industry, and a joyful approach to your public life.', 'Thách thức cần lưu ý: A lack of follow-through on grand career visions, ignoring the mundane details required for success, and a reputation for being unreliable or overly blunt.', 'You need a partner who understands that your career requires immense freedom and perhaps frequent travel. You cannot thrive in a restrictive domestic environment.', 'Cultivate professional discipline. Learn that achieving grand visions requires mastering the boring, mundane details. Ground your optimism in practical reality.', ARRAY['Nhà 10', 'Nhân Mã']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '10', 'Capricorn', '', 'Sự nghiệp, uy tín xã hội và mục tiêu dài hạn phản ánh bản lĩnh kỷ luật, trách nhiệm và thực tế của Ma Kết. Bạn xây dựng chỗ đứng và danh tiếng một cách kiên trì, bài bản và có tầm nhìn dài hạn.', 'Trong cuộc sống hằng ngày, vị trí Nhà 10 ở Ma Kết định hình phản ứng thực tế và cách bạn thể hiện bản thân. This is the natural home of Capricorn. You are highly disciplined, stoic, and willing to work for decades to achieve your goals. You project an aura of absolute competence and traditional authority.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 10 và năng lượng Ma Kết: Unmatched executive functioning, the ability to build lasting professional empires, incredible resilience, and a pristine reputation built on hard work.', 'Thách thức cần lưu ý: Workaholism, emotional coldness in public, prioritizing career success over all personal relationships, and a deep-seated fear of public failure.', 'Your career often takes precedence over your relationships. You seek a partner who is equally ambitious or who is willing to fully support your ascent to the top.', 'Remember that you are more than your job title. Cultivate a life outside of your career and allow yourself to experience joy and emotional connection without feeling guilty.', ARRAY['Nhà 10', 'Ma Kết']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '10', 'Aquarius', '', 'Sự nghiệp, uy tín xã hội và mục tiêu dài hạn phản ánh bản lĩnh độc đáo, tiến bộ và hướng tới cộng đồng của Bảo Bình. Bạn xây dựng chỗ đứng và danh tiếng một cách đột phá, trí tuệ và phi truyền thống.', 'Trong cuộc sống hằng ngày, vị trí Nhà 10 ở Bảo Bình định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are drawn to careers involving technology, science, or social reform. You reject traditional corporate structures, preferring to work independently or in egalitarian groups.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 10 và năng lượng Bảo Bình: Brilliant professional originality, the courage to challenge outdated industry norms, a humanitarian approach to business, and a highly unique public persona.', 'Thách thức cần lưu ý: Rebelling against authority just to be contrary, emotional detachment that alienates colleagues, and an unpredictable career path that lacks stability.', 'You view your professional network as a community. You need a partner who respects your unconventional career choices and your need for absolute intellectual freedom.', 'Learn to integrate your brilliant innovations into existing structures. True reform often requires working from within the system rather than just rebelling against it from the outside.', ARRAY['Nhà 10', 'Bảo Bình']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '10', 'Pisces', '', 'Sự nghiệp, uy tín xã hội và mục tiêu dài hạn phản ánh bản lĩnh mềm mại, vị tha và sâu sắc của Song Ngư. Bạn xây dựng chỗ đứng và danh tiếng một cách thấu cảm, lãng mạn và giàu trí tưởng tượng.', 'Trong cuộc sống hằng ngày, vị trí Nhà 10 ở Song Ngư định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are drawn to careers in the arts, healing professions, or spirituality. Your public image is often mysterious, glamorous, or perceived as deeply compassionate and sacrificing.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 10 và năng lượng Song Ngư: Immense creative and spiritual inspiration in your work, the ability to touch the masses on an emotional level, and a profound dedication to serving humanity.', 'Thách thức cần lưu ý: A lack of professional boundaries, chronic disorganization, getting lost in career fantasies rather than taking practical steps, and a tendency to play the victim in the workplace.', 'You often merge your career with your spiritual or romantic ideals. You need a highly grounded partner to help manage the practical details of your public life.', 'Ground your vast professional dreams in practical reality. Establish strong boundaries so that your compassion is not exploited by your industry or your colleagues.', ARRAY['Nhà 10', 'Song Ngư']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '11', 'Aries', '', 'Mạng lưới cộng đồng, bạn bè và những khát vọng tương lai mang tinh thần tiên phong, quyết đoán và độc lập của Bạch Dương. Bạn gắn kết với tập thể một cách trực diện, dũng cảm và nhiệt huyết.', 'Trong cuộc sống hằng ngày, vị trí Nhà 11 ở Bạch Dương định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are the initiator in your social circle, always organizing activities or championing new causes. You attract energetic, independent friends and prefer active group settings.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 11 và năng lượng Bạch Dương: Natural leadership within organizations, the courage to fight for collective goals, and an infectious enthusiasm that motivates your network.', 'Thách thức cần lưu ý: Dominating friend groups, impulsiveness that alienates more cautious allies, a tendency to argue with friends, and losing interest in causes quickly.', 'You need friends who respect your independence and can match your high energy. You may clash with overly sensitive individuals in group settings.', 'Learn to be a team player, not just the team captain. True collective progress requires listening to the ideas of others and compromising.', ARRAY['Nhà 11', 'Bạch Dương']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '11', 'Taurus', '', 'Mạng lưới cộng đồng, bạn bè và những khát vọng tương lai mang tinh thần kiên định, bền bỉ và thực tế của Kim Ngưu. Bạn gắn kết với tập thể một cách vững chắc, cẩn trọng và coi trọng chất lượng.', 'Trong cuộc sống hằng ngày, vị trí Nhà 11 ở Kim Ngưu định hình phản ứng thực tế và cách bạn thể hiện bản thân. You take a long time to make friends, but once you do, they are friends for life. You prefer small, intimate group gatherings centered around good food, art, or nature.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 11 và năng lượng Kim Ngưu: Unwavering loyalty to your network, the ability to provide practical support to organizations, and a calming, steady presence in any group setting.', 'Thách thức cần lưu ý: Stubbornness within group dynamics, a reluctance to welcome new people into your established circle, and prioritizing material status in your friendships.', 'You view your friends as an extension of your family. You require absolute reliability from your social network and express care through tangible support.', 'Be open to new associations and unconventional ideas. Do not let your need for comfort prevent you from engaging with diverse groups of people.', ARRAY['Nhà 11', 'Kim Ngưu']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '11', 'Gemini', '', 'Mạng lưới cộng đồng, bạn bè và những khát vọng tương lai mang tinh thần nhanh trí, linh hoạt và tò mò của Song Tử. Bạn gắn kết với tập thể một cách cởi mở, đa dạng và giỏi giao tiếp.', 'Trong cuộc sống hằng ngày, vị trí Nhà 11 ở Song Tử định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are a social butterfly, belonging to numerous different groups and clubs. You love networking, sharing information, and connecting people with disparate interests.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 11 và năng lượng Song Tử: Exceptional networking skills, the ability to bridge communication gaps within organizations, and a brilliant, adaptable approach to collective goals.', 'Thách thức cần lưu ý: Superficial friendships, a lack of deep loyalty to any single group, a tendency to gossip, and scattering your social energy too thinly.', 'You need friends who are intellectually stimulating and constantly changing. You quickly lose interest in social circles that become stagnant or overly emotional.', 'Cultivate depth in your friendships. While having a vast network is a strength, taking the time to build profound, lasting bonds with a few individuals is equally important.', ARRAY['Nhà 11', 'Song Tử']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '11', 'Cancer', '', 'Mạng lưới cộng đồng, bạn bè và những khát vọng tương lai mang tinh thần nhạy cảm, thấu cảm và chu đáo của Cự Giải. Bạn gắn kết với tập thể một cách ấm áp, bảo vệ và giàu tình cảm.', 'Trong cuộc sống hằng ngày, vị trí Nhà 11 ở Cự Giải định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are drawn to groups that focus on caregiving, community support, or shared heritage. You are fiercely protective of your social circle and often take on a maternal role within groups.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 11 và năng lượng Cự Giải: Profound emotional support for your network, the ability to create a deep sense of belonging within organizations, and fierce loyalty to your "tribe."', 'Thách thức cần lưu ý: Cliquishness, a fear of outsiders, taking group disagreements intensely personally, and a tendency to smother friends with over-protectiveness.', 'You need a social circle where you feel completely emotionally safe. You express your friendship through cooking, nurturing, and offering a shoulder to cry on.', 'Learn to establish emotional boundaries within your friendships. Understand that not everyone in your group needs to be "mothered," and practice welcoming new faces without suspicion.', ARRAY['Nhà 11', 'Cự Giải']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '11', 'Leo', '', 'Mạng lưới cộng đồng, bạn bè và những khát vọng tương lai mang tinh thần kiêu hãnh, tự tin và sáng tạo của Sư Tử. Bạn gắn kết với tập thể một cách rực rỡ, hào phóng và cuốn hút.', 'Trong cuộc sống hằng ngày, vị trí Nhà 11 ở Sư Tử định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are generous, popular, and often take on leadership roles in clubs or organizations. You love hosting grand social events and expect admiration from your peers.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 11 và năng lượng Sư Tử: Immense generosity toward friends, charismatic leadership within groups, the ability to inspire collective joy, and unwavering loyalty to your inner circle.', 'Thách thức cần lưu ý: Arrogance, a need to constantly be the center of attention in group settings, dominating conversations, and turning friendships into a stage for your ego.', 'You expect your friends to be your biggest fans and to treat you with respect. You are deeply hurt if you feel ignored or unappreciated by your network.', 'Learn that true friendship involves sharing the spotlight. Allow your friends to shine and realize that you do not always have to be the leader to be loved.', ARRAY['Nhà 11', 'Sư Tử']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '11', 'Libra', '', 'Mạng lưới cộng đồng, bạn bè và những khát vọng tương lai mang tinh thần hài hòa, lịch thiệp và công bằng của Thiên Bình. Bạn gắn kết với tập thể một cách khéo léo, tinh tế và hướng tới sự cân bằng.', 'Trong cuộc sống hằng ngày, vị trí Nhà 11 ở Thiên Bình định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are highly popular, diplomatic, and skilled at bringing people together. You prefer refined social settings and often act as the peacemaker within your friend group.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 11 và năng lượng Thiên Bình: Exceptional mediation skills within organizations, a talent for creating beautiful and harmonious social events, and a deep dedication to fairness and equality in groups.', 'Thách thức cần lưu ý: Indecisiveness, agreeing with the group just to keep the peace (groupthink), a fear of confronting toxic friends, and relying too heavily on your social network for your identity.', 'You thrive in partnerships and cooperative group settings. You detest crude behavior or conflict within your social circle and will go to great lengths to maintain harmony.', 'Develop the courage to stand alone and voice unpopular opinions. True friendship requires honesty, even when it disrupts the peace.', ARRAY['Nhà 11', 'Thiên Bình']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '11', 'Scorpio', '', 'Mạng lưới cộng đồng, bạn bè và những khát vọng tương lai mang tinh thần sâu sắc, kiên cường và thâm trầm của Bọ Cạp. Bạn gắn kết với tập thể một cách mãnh liệt, trực giác và bí ẩn.', 'Trong cuộc sống hằng ngày, vị trí Nhà 11 ở Bọ Cạp định hình phản ứng thực tế và cách bạn thể hiện bản thân. You prefer a very small, tightly-knit circle of fiercely loyal friends over a large network of acquaintances. You are drawn to groups involved in psychology, investigation, or the occult.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 11 và năng lượng Bọ Cạp: Unwavering loyalty to your inner circle, the ability to support friends through massive psychological crises, and profound insight into group dynamics.', 'Thách thức cần lưu ý: Paranoia regarding outsiders, extreme possessiveness or jealousy in friendships, holding long-term grudges, and a tendency to engage in power struggles within organizations.', 'You demand absolute transparency and trust from your friends. Betrayal is unforgivable. You are a formidable ally but a terrifying enemy.', 'Learn to trust people outside your immediate circle. Release the need to control your friendships and realize that not everyone has hidden, malicious motives.', ARRAY['Nhà 11', 'Bọ Cạp']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '11', 'Capricorn', '', 'Mạng lưới cộng đồng, bạn bè và những khát vọng tương lai mang tinh thần kỷ luật, trách nhiệm và thực tế của Ma Kết. Bạn gắn kết với tập thể một cách kiên trì, bài bản và có tầm nhìn dài hạn.', 'Trong cuộc sống hằng ngày, vị trí Nhà 11 ở Ma Kết định hình phản ứng thực tế và cách bạn thể hiện bản thân. You are highly selective about your friends, preferring individuals who are mature, successful, or influential. You often take on administrative or leadership roles within organizations.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 11 và năng lượng Ma Kết: Exceptional reliability, the ability to manifest grand collective goals through strategic planning, and a steadfast, mature approach to supporting your network.', 'Thách thức cần lưu ý: Viewing friendships purely as networking opportunities, emotional coldness within social groups, pessimism, and a fear of letting your guard down to simply have fun.', 'You express care through mentorship and practical support. You respect authority and structure within groups and have little patience for disorganized or frivolous social circles.', 'Remember that friendships are about emotional connection, not just professional advancement. Allow yourself to be vulnerable and enjoy the simple pleasure of human companionship.', ARRAY['Nhà 11', 'Ma Kết']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '12', 'Aries', '', 'Thế giới tiềm thức, trực giác tâm linh và hành trình chữa lành mang năng lượng tiên phong, quyết đoán và độc lập của Bạch Dương. Bạn tìm thấy sự an trú nội tâm một cách trực diện, dũng cảm và nhiệt huyết.', 'Trong cuộc sống hằng ngày, vị trí Nhà 12 ở Bạch Dương định hình phản ứng thực tế và cách bạn thể hiện bản thân. You may project a calm exterior but struggle with intense, hidden frustrations or impulsive urges. You often prefer to work entirely alone and may act as a secret pioneer or hidden leader.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 12 và năng lượng Bạch Dương: The ability to fight fiercely for the underdog in secret, immense hidden reserves of energy that emerge in crises, and courage in exploring the deepest psychological shadows.', 'Thách thức cần lưu ý: Repressed anger that erupts unexpectedly, self-sabotage through impulsive, hidden actions, and a fear of expressing your true assertiveness openly.', 'Your spiritual journey requires confronting your inner warrior. You may feel isolated because you hide your most passionate, driven self from the world.', 'Bring your hidden anger and desires into the light. Learn healthy ways to assert yourself publicly so that your repressed energy does not destroy you from within.', ARRAY['Nhà 12', 'Bạch Dương']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '12', 'Taurus', '', 'Thế giới tiềm thức, trực giác tâm linh và hành trình chữa lành mang năng lượng kiên định, bền bỉ và thực tế của Kim Ngưu. Bạn tìm thấy sự an trú nội tâm một cách vững chắc, cẩn trọng và coi trọng chất lượng.', 'Trong cuộc sống hằng ngày, vị trí Nhà 12 ở Kim Ngưu định hình phản ứng thực tế và cách bạn thể hiện bản thân. You may hide your true desires for luxury or material wealth, projecting a detached exterior. Your spiritual journey involves grounding yourself, often finding peace in isolated natural settings.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 12 và năng lượng Kim Ngưu: A profound, hidden endurance, the ability to manifest material results quietly behind the scenes, and a deeply sensual, unspoken connection to nature and spirituality.', 'Thách thức cần lưu ý: Repressed greed or materialism, an extreme fear of financial loss that dictates your subconscious actions, and a stubborn refusal to let go of hidden emotional baggage.', 'You seek spiritual peace through physical comfort and silence. You are a reliable, unseen supporter of others, often providing material help anonymously.', 'Acknowledge your material desires without guilt. True spiritual growth requires realizing that the physical world and the spiritual world are not mutually exclusive.', ARRAY['Nhà 12', 'Kim Ngưu']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '12', 'Gemini', '', 'Thế giới tiềm thức, trực giác tâm linh và hành trình chữa lành mang năng lượng nhanh trí, linh hoạt và tò mò của Song Tử. Bạn tìm thấy sự an trú nội tâm một cách cởi mở, đa dạng và giỏi giao tiếp.', 'Trong cuộc sống hằng ngày, vị trí Nhà 12 ở Song Tử định hình phản ứng thực tế và cách bạn thể hiện bản thân. Your mind is constantly racing, even when you appear calm. You may struggle with insomnia or hidden nervous tension. You find spiritual connection through isolated study, writing, or quiet contemplation.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 12 và năng lượng Song Tử: A brilliant, intuitive mind that operates behind the scenes, the ability to act as a secret communicator or writer, and a profound, hidden understanding of duality.', 'Thách thức cần lưu ý: Repressed anxiety, an inability to quiet the mind during meditation, keeping your true thoughts a secret out of fear of judgment, and self-sabotage through overthinking.', 'Your spiritual journey requires calming the mental noise. You may struggle to communicate your deepest, most profound insights, preferring to keep them hidden.', 'Practice meditation and mindfulness to silence your inner chatter. Learn to trust your intuition rather than constantly analyzing your subconscious feelings.', ARRAY['Nhà 12', 'Song Tử']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '12', 'Cancer', '', 'Thế giới tiềm thức, trực giác tâm linh và hành trình chữa lành mang năng lượng nhạy cảm, thấu cảm và chu đáo của Cự Giải. Bạn tìm thấy sự an trú nội tâm một cách ấm áp, bảo vệ và giàu tình cảm.', 'Trong cuộc sống hằng ngày, vị trí Nhà 12 ở Cự Giải định hình phản ứng thực tế và cách bạn thể hiện bản thân. You absorb the emotions of the world like a sponge and require frequent periods of total isolation to emotionally recharge. Your inner world is a vast, sensitive ocean of memory and feeling.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 12 và năng lượng Cự Giải: Supreme emotional intuition, the ability to heal others on a profound, unspoken level, and a deep, mystical connection to your ancestors and the collective unconscious.', 'Thách thức cần lưu ý: Repressed childhood trauma, debilitating hidden fears of abandonment, playing the martyr in secret, and self-sabotaging out of a deep-seated feeling of emotional insecurity.', 'Your spiritual path involves nurturing your own soul. You are a powerful, hidden healer who deeply understands the unspoken pain of humanity.', 'Confront your hidden emotional wounds. Do not retreat into isolation permanently; learn to establish boundaries so you can share your immense empathy with the world safely.', ARRAY['Nhà 12', 'Cự Giải']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '12', 'Leo', '', 'Thế giới tiềm thức, trực giác tâm linh và hành trình chữa lành mang năng lượng kiêu hãnh, tự tin và sáng tạo của Sư Tử. Bạn tìm thấy sự an trú nội tâm một cách rực rỡ, hào phóng và cuốn hút.', 'Trong cuộc sống hằng ngày, vị trí Nhà 12 ở Sư Tử định hình phản ứng thực tế và cách bạn thể hiện bản thân. You may hide your true creative talents or your desire for the spotlight, perhaps feeling unworthy of attention. You often perform great acts of generosity anonymously or work as a hidden leader.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 12 và năng lượng Sư Tử: Immense, hidden creative power, a deeply warm and radiant inner life, and the ability to inspire and lead others from behind the scenes without seeking credit.', 'Thách thức cần lưu ý: Repressed ego that manifests as secret vanity or bitterness, self-sabotaging your own success out of a fear of public failure, and hiding your true, radiant self.', 'Your spiritual journey requires acknowledging your own intrinsic worth. You have a profound capacity for unconditional love that you often keep hidden from the world.', 'Allow your inner light to shine publicly. Do not hide your talents or your pride out of a false sense of modesty. You deserve to be seen.', ARRAY['Nhà 12', 'Sư Tử']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '12', 'Virgo', '', 'Thế giới tiềm thức, trực giác tâm linh và hành trình chữa lành mang năng lượng tỉ mỉ, cẩn thận và thực tế của Xử Nữ. Bạn tìm thấy sự an trú nội tâm một cách chỉn chu, phân tích và có phương pháp.', 'Trong cuộc sống hằng ngày, vị trí Nhà 12 ở Xử Nữ định hình phản ứng thực tế và cách bạn thể hiện bản thân. You may struggle with hidden anxieties regarding your health or competence. You find spiritual peace through quiet, practical service to others or through solitary, detailed work.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 12 và năng lượng Xử Nữ: A profound ability to analyze the subconscious mind, selfless dedication to helping the most marginalized in society, and exceptional behind-the-scenes organizational skills.', 'Thách thức cần lưu ý: Crippling, hidden self-criticism, psychosomatic illnesses driven by repressed anxiety, and self-sabotage by obsessing over minor flaws in your own psyche.', 'Your spiritual path involves realizing that perfection is an illusion. You are a quiet, humble servant to humanity, often doing the difficult work that no one else wants to do.', 'Silence your hidden inner critic. Learn to accept yourself unconditionally and realize that your worth is not defined by how perfectly you serve others.', ARRAY['Nhà 12', 'Xử Nữ']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '12', 'Libra', '', 'Thế giới tiềm thức, trực giác tâm linh và hành trình chữa lành mang năng lượng hài hòa, lịch thiệp và công bằng của Thiên Bình. Bạn tìm thấy sự an trú nội tâm một cách khéo léo, tinh tế và hướng tới sự cân bằng.', 'Trong cuộc sống hằng ngày, vị trí Nhà 12 ở Thiên Bình định hình phản ứng thực tế và cách bạn thể hiện bản thân. You may hide your true opinions to avoid conflict, harboring secret resentments. You find spiritual peace in beautifully aesthetic, isolated environments and may act as a hidden peacemaker.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 12 và năng lượng Thiên Bình: A profound, unspoken understanding of human relationships, the ability to restore balance behind the scenes, and a deeply refined, artistic inner life.', 'Thách thức cần lưu ý: Repressed anger due to people-pleasing, self-sabotaging through hidden codependent behaviors, and a fear of confronting your own shadow self because it is "ugly."', 'Your spiritual journey requires finding inner balance independent of any partner. You possess a beautiful soul, but you often suppress your own needs for the sake of artificial peace.', 'Confront your hidden resentments. True spiritual harmony requires acknowledging both the light and the dark within yourself, and asserting your own needs openly.', ARRAY['Nhà 12', 'Thiên Bình']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '12', 'Scorpio', '', 'Thế giới tiềm thức, trực giác tâm linh và hành trình chữa lành mang năng lượng sâu sắc, kiên cường và thâm trầm của Bọ Cạp. Bạn tìm thấy sự an trú nội tâm một cách mãnh liệt, trực giác và bí ẩn.', 'Trong cuộc sống hằng ngày, vị trí Nhà 12 ở Bọ Cạp định hình phản ứng thực tế và cách bạn thể hiện bản thân. You possess a terrifyingly accurate intuition and are drawn to the deepest mysteries of the occult and human psychology. Your inner world is a crucible of intense, hidden passions and fears.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 12 và năng lượng Bọ Cạp: Unmatched psychological depth, the ability to heal the most profound traumas in yourself and others, and immense spiritual power that operates unseen.', 'Thách thức cần lưu ý: Repressed paranoia, hidden obsessions, holding onto dark secrets that poison your soul, and self-sabotage through a subconscious desire for destruction.', 'Your spiritual path is one of radical transformation. You must continually let go of your ego and face the darkest parts of your soul to achieve true enlightenment.', 'Do not fear your own intensity. Bring your hidden fears and desires into the light where they can be healed. Use your immense power for spiritual regeneration, not self-destruction.', ARRAY['Nhà 12', 'Bọ Cạp']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '12', 'Sagittarius', '', 'Thế giới tiềm thức, trực giác tâm linh và hành trình chữa lành mang năng lượng phóng khoáng, lạc quan và yêu tự do của Nhân Mã. Bạn tìm thấy sự an trú nội tâm một cách thẳng thắn, rộng mở và giàu lý tưởng.', 'Trong cuộc sống hằng ngày, vị trí Nhà 12 ở Nhân Mã định hình phản ứng thực tế và cách bạn thể hiện bản thân. You may hide your true philosophical beliefs or your desire to escape the mundane world. You find profound spiritual connection through solitary travel or isolated study of grand concepts.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 12 và năng lượng Nhân Mã: A vast, visionary inner life, the ability to act as a hidden spiritual guide or teacher, and profound, unspoken optimism and faith in the universe.', 'Thách thức cần lưu ý: Repressed restlessness, self-sabotage through hidden recklessness or gambling, and a tendency to run away from reality by retreating into grand, unrealistic fantasies.', 'Your spiritual journey involves finding ultimate truth within yourself. You possess a deep, innate wisdom that you often share quietly with those who are lost.', 'Ground your spiritual visions in reality. You do not need to constantly escape to find truth; true freedom and wisdom can be found exactly where you are.', ARRAY['Nhà 12', 'Nhân Mã']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '12', 'Capricorn', '', 'Thế giới tiềm thức, trực giác tâm linh và hành trình chữa lành mang năng lượng kỷ luật, trách nhiệm và thực tế của Ma Kết. Bạn tìm thấy sự an trú nội tâm một cách kiên trì, bài bản và có tầm nhìn dài hạn.', 'Trong cuộc sống hằng ngày, vị trí Nhà 12 ở Ma Kết định hình phản ứng thực tế và cách bạn thể hiện bản thân. You may project a carefree exterior while harboring intense, secret ambitions or heavy burdens of guilt. You find spiritual strength through solitude, discipline, and facing harsh realities.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 12 và năng lượng Ma Kết: Immense, hidden resilience, the ability to bear incredible psychological burdens without complaining, and a profound, stoic spiritual wisdom acquired through hardship.', 'Thách thức cần lưu ý: Repressed pessimism, crippling hidden guilt or fear of inadequacy, self-sabotaging your own joy out of a belief that you must suffer, and emotional isolation.', 'Your spiritual path requires dismantling the rigid structures of your ego. You are a silent pillar of strength for others, often carrying the weight of the world in secret.', 'Release your hidden guilt and your need for absolute control. True spiritual mastery requires vulnerability and the ability to forgive yourself for not being perfect.', ARRAY['Nhà 12', 'Ma Kết']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '12', 'Aquarius', '', 'Thế giới tiềm thức, trực giác tâm linh và hành trình chữa lành mang năng lượng độc đáo, tiến bộ và hướng tới cộng đồng của Bảo Bình. Bạn tìm thấy sự an trú nội tâm một cách đột phá, trí tuệ và phi truyền thống.', 'Trong cuộc sống hằng ngày, vị trí Nhà 12 ở Bảo Bình định hình phản ứng thực tế và cách bạn thể hiện bản thân. You may feel like an alien observing the world, hiding your true, eccentric brilliance for fear of rejection. You find spiritual peace through solitary intellectual pursuits or hidden humanitarian work.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 12 và năng lượng Bảo Bình: A brilliant, profoundly original subconscious mind, the ability to channel futuristic or collective insights, and a selfless, detached dedication to helping the marginalized.', 'Thách thức cần lưu ý: Repressed rebellion that erupts inappropriately, a deep, hidden fear of intimacy that isolates you, and self-sabotage by disconnecting completely from your own emotions.', 'Your spiritual journey requires integrating your brilliant mind with the collective heart of humanity. You are a hidden innovator, working quietly to advance the collective consciousness.', 'Do not isolate yourself out of a belief that no one understands you. Embrace your unique brilliance and learn to connect with others emotionally, not just intellectually.', ARRAY['Nhà 12', 'Bảo Bình']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'house_in_sign', '12', 'Pisces', '', 'Thế giới tiềm thức, trực giác tâm linh và hành trình chữa lành mang năng lượng mềm mại, vị tha và sâu sắc của Song Ngư. Bạn tìm thấy sự an trú nội tâm một cách thấu cảm, lãng mạn và giàu trí tưởng tượng.', 'Trong cuộc sống hằng ngày, vị trí Nhà 12 ở Song Ngư định hình phản ứng thực tế và cách bạn thể hiện bản thân. This is the natural home of Pisces. The boundaries between your conscious mind and the spiritual world are incredibly thin. You require vast amounts of solitude to process the immense energies you absorb.', 'Sức mạnh nổi bật đến từ sự kết hợp giữa lĩnh vực Nhà 12 và năng lượng Song Ngư: Supreme spiritual intuition, boundless compassion for all living things, the ability to channel profound art or healing, and a natural state of mystical enlightenment.', 'Thách thức cần lưu ý: A complete lack of psychological boundaries, getting lost in illusions, addictions, or severe escapism to avoid the harshness of reality, and extreme martyrdom.', 'Your spiritual path is your entire life. You are a natural mystic and healer, but you are highly vulnerable to the dark energies of the world if you do not protect yourself.', 'Establish iron-clad boundaries. You cannot heal the world if you allow yourself to drown in its sorrow. Ground your immense spiritual power in practical reality.', ARRAY['Nhà 12', 'Song Ngư']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges;
